      const r = run2(bad);
      expect(r.error).not.toBeNull();
      expect(r.error!.line).toBe(1);
      expect(r.error!.column).toBe(4);
      expect(r.segments).toEqual([]);
    }
  });

  test('znak jest operatorem, a nie częścią liczby', () => {
    expect(run2('np -5').segments[0]!.to).toEqual([0, -5, 0]);
