    expect(len('niech bok 4 np -bok')).toBe(-4);
    expect(len('niech bok 4 np - - bok')).toBe(4);
    expect(len('np -2 * 3')).toBe(-6);
  });

  test('argumenty procedur: kolejna wartość może zaczynać się od znaku', () => {
    const r = run2('oto f ma: a, b\n np a\n pw 90\n np b\njuż\nf 10 -5');
