    expect(run2('powtorz 4999 [jeśli 1 = 2 [pod]]').error).toBeNull();
    expect(run2('powtorz 5000 [jeśli 1 = 2 [pod]]').error).not.toBeNull();
  });

  test('współrzędne w zakresie ±100 000', () => {
