      const a = this.anim;
      const k = clamp((now - a.t0) / a.dur, 0, 1);
      const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
      a.step(e);
      if (k >= 1) {
