    if (!this.canvas.width) this.resize();
    const ctx = this.ctx;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.draw(ctx, this.width, this.height, { palette: this.palette, exporting: false });
