            h('p', { class: 'muted' }, ex.tagline),
            h(
              'div',
              { class: 'card-actions' },
              h('button', {
                class: 'btn btn-primary btn-sm', type: 'button', 'aria-label': `Wczytaj przykład ${ex.name} do pracowni`,
                onclick: () => this.app.loadExampleInStudio(ex.id),
