import { chromium } from 'playwright';
export async function withPage(fn, { w = 1360, h = 800, scheme = 'light', url = 'http://localhost:4173/', touch = false, storage = null } = {}) {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, colorScheme: scheme, deviceScaleFactor: touch ? 2 : 1, hasTouch: touch, isMobile: touch, acceptDownloads: true, permissions: ['clipboard-read', 'clipboard-write'] });
  const page = await ctx.newPage();
  const logs = [];
  page.on('console', (m) => { if (m.type() !== 'log' || true) logs.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
  page.on('crash', () => logs.push('PAGE CRASH'));
  if (storage) await ctx.addInitScript((s) => { for (const [k, v] of Object.entries(s)) localStorage.setItem(k, v); }, storage);
  await page.goto(url);
  await page.waitForFunction(() => window.logomocja);
  await page.waitForTimeout(500);
  let result;
  try { result = await fn(page, ctx); } finally {
    if (logs.length) console.log('--- console ---\n' + logs.join('\n'));
    await browser.close();
  }
  return result;
}
EOF
