import { withPage } from './lib.mjs';
import fs from 'node:fs';
const ok = (c, m) => console.log((c ? 'PASS' : 'FAIL') + ' ' + m);

await withPage(async (page, ctx) => {
  // 1. Share link
  await page.evaluate(() => window.logomocja.open('powtorz 5 [np 100 pw 144]', '2d'));
  await page.click('button[aria-label="Link"]');
  await page.waitForSelector('dialog[open] input#permalink-input');
  const url = await page.inputValue('#permalink-input');
  ok(url.includes('#/?tryb=2d&kod='), 'permalink format: ' + url.slice(0, 80));
  ok((await page.evaluate(() => location.href)) === url, 'address bar equals permalink');
  await page.click('dialog[open] button:has-text("Kopiuj link")');
  await page.waitForTimeout(200);
  const clip = await page.evaluate(() => navigator.clipboard.readText());
  ok(clip === url, 'clipboard has the link');
  await page.keyboard.press('Escape');
  const p2 = await ctx.newPage();
  await p2.goto(url);
  await p2.waitForFunction(() => window.logomocja);
  await p2.waitForTimeout(800);
  const text = await p2.inputValue('.editor-input');
  ok(text === 'powtorz 5 [np 100 pw 144]', 'permalink loads program: ' + JSON.stringify(text));
  ok((await p2.textContent('.view-badge')) === '5 odcinków', 'permalink ran program: ' + (await p2.textContent('.view-badge')));
  ok(!(await p2.evaluate(() => location.hash.includes('kod='))), 'permalink consumed from URL: ' + await p2.evaluate(() => location.hash));
  await p2.close();

  // 2. Download
  const [dl] = await Promise.all([page.waitForEvent('download'), page.click('button[title*="Pobierz program"]')]);
  const name = dl.suggestedFilename();
  const body = fs.readFileSync(await dl.path(), 'utf8');
  ok(name.endsWith('.logo'), 'download name ' + name);
  ok(body === 'powtorz 5 [np 100 pw 144]', 'download content');

  // 3. Open file
  fs.writeFileSync('/tmp/test3d.logo', 'gora 90\nnp 50\n; plik z 3D\n');
  await page.setInputFiles('input[type=file]', '/tmp/test3d.logo');
  await page.waitForTimeout(600);
  ok((await page.inputValue('.editor-input')) === 'gora 90\nnp 50\n; plik z 3D\n', 'file content loaded');
  ok(await page.isChecked('input[type=radio][value="3d"]'), 'mode switched to 3D by file content');
  const toastTxt = await page.textContent('.toasts');
  ok(/zachowan/.test(toastTxt), 'stash toast shown on replacing user draft: ' + toastTxt.replace(/\s+/g, ' '));

  // 4. PNG export
  await page.evaluate(() => window.logomocja.open('powtorz 5 [np 100 pw 144]', '2d'));
  const [png] = await Promise.all([page.waitForEvent('download'), page.click('.transport button[aria-label="PNG"]')]);
  const buf = fs.readFileSync(await png.path());
  ok(buf.subarray(0, 8).toString('hex') === '89504e470d0a1a0a', 'PNG signature, size ' + buf.length + ' name ' + png.suggestedFilename());
  fs.writeFileSync('/tmp/export.png', buf);
});
EOF
