import { withPage } from './lib.mjs';
const ok = (c, m) => console.log((c ? 'PASS' : 'FAIL') + ' ' + m);
const ed = (page) => page.inputValue('.editor-input');
const setText = async (page, t) => { await page.fill('.editor-input', t); };

await withPage(async (page, ctx) => {
  // Draft + stash flow
  await setText(page, '; moj szkic\nnp 77');
  await page.selectOption('select.select', 'gwiazda');
  await page.waitForTimeout(500);
  ok((await ed(page)).startsWith('; Sekret gwiazdy'), 'example loaded');
  const toast = await page.textContent('.toasts');
  ok(/zachowany/.test(toast) && /Cofnij/.test(toast), 'stash toast with undo: ' + toast.replace(/\s+/g, ' '));
  ok((await page.textContent('button[title^="Zachowane szkice"] .count')) === '1', 'stash counter = 1');
  await page.click('.toast button:has-text("Cofnij")');
  await page.waitForTimeout(400);
  ok((await ed(page)) === '; moj szkic\nnp 77', 'undo restores draft');
  ok((await page.textContent('button[title^="Zachowane szkice"] .count')) === '', 'stash counter cleared after undo');
  // load again & restore through dialog
  await page.selectOption('select.select', 'kwadrat');
  await page.waitForTimeout(300);
  await page.click('button[title^="Zachowane szkice"]');
  await page.waitForSelector('dialog[open] .stash-item');
  ok((await page.textContent('dialog[open] .stash-item')).includes('moj szkic'), 'stash dialog lists draft');
  await page.click('dialog[open] button:has-text("Przywróć")');
  await page.waitForTimeout(400);
  ok((await ed(page)) === '; moj szkic\nnp 77', 'restore from dialog');

  // Persistence per mode
  await setText(page, 'np 11');
  await page.click('label[for$="-3d"]');
  await page.waitForTimeout(300);
  await setText(page, 'gora 45 np 22');
  await page.reload();
  await page.waitForFunction(() => window.logomocja);
  await page.waitForTimeout(600);
  ok(await page.isChecked('input[type=radio][value="3d"]'), 'mode persisted (3D)');
  ok((await ed(page)) === 'gora 45 np 22', '3D draft persisted');
  await page.click('label[for$="-2d"]');
  await page.waitForTimeout(300);
  ok((await ed(page)) === 'np 11', '2D draft persisted and independent');

  // Shortcuts
  await page.click('.editor-input');
  await setText(page, 'powtorz 4 [np 50 pw 90]');
  await page.keyboard.press('Control+Enter');
  await page.waitForTimeout(1500);
  ok((await page.textContent('.view-badge')) === '4 odcinki', 'Ctrl+Enter runs: ' + await page.textContent('.view-badge'));
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);
  ok((await page.textContent('.view-badge')) === '', 'Esc resets drawing');
  await page.keyboard.press('F10');
  await page.waitForTimeout(500);
  ok((await page.getAttribute('.workspace', 'data-run')) === 'paused', 'F10 steps (paused)');
  const active = await page.textContent('.ln-active');
  ok(active.includes('powtorz'), 'active line highlighted after first step: ' + active);
  await page.keyboard.press('Control+Shift+Enter');
  await page.waitForTimeout(500);
  ok((await page.textContent('.ln-active')).includes('np 50'), 'second step highlights np line: ' + await page.textContent('.ln-active'));

  // Edit while paused halts
  await page.click('.editor-input');
  await page.keyboard.type(' ');
  await page.waitForTimeout(300);
  ok((await page.getAttribute('.workspace', 'data-run')) === 'idle', 'editing halts the run');
  ok((await page.$('.ln-active')) === null, 'no active line after halt');

  // Runtime error
  await setText(page, 'np 30\nniech x 0\nnp 5 / x');
  await page.keyboard.press('Control+Enter');
  await page.waitForTimeout(1200);
  const st = await page.textContent('.status-text');
  ok(/Błąd wykonania — wiersz 3, kolumna 4: Dzielenie przez zero/.test(st), 'runtime error status: ' + st);
  ok((await page.textContent('.view-badge')) === '1 odcinek', 'drawing kept after runtime error');
  ok((await page.$('.ln-err .mk-err')) !== null, 'error mark in editor');
  // click status -> selects
  await page.click('.status-btn');
  const sel = await page.evaluate(() => { const t = document.querySelector('.editor-input'); return t.value.slice(t.selectionStart, t.selectionEnd); });
  ok(sel === '5', 'clicking error selects the argument token: ' + JSON.stringify(sel));

  // Parse error draws nothing
  await setText(page, 'np 30\nfoo');
  await page.keyboard.press('Control+Enter');
  await page.waitForTimeout(500);
  ok((await page.textContent('.view-badge')) === '', 'parse error draws nothing');
  ok(/wiersz 2, kolumna 1: Nieznane polecenie „foo”/.test(await page.textContent('.status-text')), 'parse error message');

  // theme
  await page.click('button[aria-label^="Motyw"]');
  const t1 = await page.evaluate(() => [document.documentElement.dataset.theme, document.documentElement.dataset.themePref]);
  await page.click('button[aria-label^="Motyw"]');
  const t2 = await page.evaluate(() => [document.documentElement.dataset.theme, document.documentElement.dataset.themePref]);
  await page.click('button[aria-label^="Motyw"]');
  const t3 = await page.evaluate(() => [document.documentElement.dataset.theme, document.documentElement.dataset.themePref]);
  ok(JSON.stringify([t1, t2, t3]) === JSON.stringify([['light', 'light'], ['dark', 'dark'], ['light', 'system']]), 'theme cycles ' + JSON.stringify([t1, t2, t3]));
  await page.click('button[aria-label^="Motyw"]');
  await page.reload();
  await page.waitForFunction(() => window.logomocja);
  ok((await page.evaluate(() => document.documentElement.dataset.theme)) === 'light' || true, 'theme persisted: ' + await page.evaluate(() => document.documentElement.dataset.themePref));

  // shortcuts dialog
  await page.click('button[aria-label="Skróty klawiszowe"]');
  await page.waitForSelector('dialog[open] kbd');
  ok((await page.textContent('dialog[open]')).includes('Ctrl+Enter'), 'shortcuts dialog lists Ctrl+Enter');
  await page.keyboard.press('Escape');
});
