1	import { LIMITS } from './limits';
2	import { normalizeName } from './keywords';
3	
4	export type TokenKind =
5	  | 'num' // liczba bez znaku
6	  | 'word' // nazwa lub słowo kluczowe
7	  | 'cname' // :nazwa (zapis dawny)
8	  | 'str' // "..." (literał koloru)
9	  | 'op' // + - * /
10	  | 'cmp' // < > = <= >= <>
11	  | 'lbr' | 'rbr' // [ ]
12	  | 'lpar' | 'rpar' // ( )
13	  | 'comma'
14	  | 'colon'
15	  | 'err'; // błąd leksykalny — zgłaszany dopiero, gdy parser do niego dojdzie
16	
17	export interface Token {
18	  kind: TokenKind;
19	  /** Tekst z kodu źródłowego. */
20	  text: string;
21	  /** Wartość liczby. */
22	  value: number;
23	  /** Znormalizowana nazwa (małe litery) dla `word` i `cname`. */
24	  name: string;
25	  line: number;
26	  col: number;
27	  start: number;
28	  end: number;
29	  spaceBefore: boolean;
30	  spaceAfter: boolean;
31	  firstOnLine: boolean;
32	  lastOnLine: boolean;
33	  /** Komunikat dla `err`. */
34	  message: string;
35	}
36	
37	export interface LexResult {
38	  tokens: Token[];
39	  /** Zakresy komentarzy (offsety początku i końca) — do podświetlania. */
40	  comments: Array<[number, number]>;
41	}
42	
43	export interface LexOptions {
44	  /** Egzekwuj limity liczby symboli (domyślnie tak). */
45	  limits?: boolean;
46	}
47	
48	const WORD_START = /[\p{L}_]/u;
49	const WORD_PART = /[\p{L}\p{M}\p{N}_]/u;
50	const WS = /\s/;
51	
52	function isDigit(c: string): boolean {
53	  return c >= '0' && c <= '9';
54	}
55	
56	function charAtCp(src: string, i: number): string {
57	  const cp = src.codePointAt(i);
58	  return cp === undefined ? '' : String.fromCodePoint(cp);
59	}
60	
61	export function lex(source: string, options: LexOptions = {}): LexResult {
62	  const limits = options.limits !== false;
63	  const tokens: Token[] = [];
64	  const comments: Array<[number, number]> = [];
65	  const n = source.length;
66	  let i = 0;
67	  let line = 1;
68	  let lineStart = 0;
69	  let lastTokenLine = 0;
70	  let stop = false;
71	
72	  const push = (kind: TokenKind, start: number, end: number, extra: Partial<Token> = {}): Token | null => {
73	    if (limits && tokens.length >= LIMITS.maxTokens) {
74	      // 10 001. symbol: błąd limitu, dalsza analiza nie ma sensu.
75	      tokens.push(makeToken('err', start, end, {
76	        message: `Przekroczono limit ${LIMITS.maxTokens.toLocaleString('pl-PL')} symboli w programie.`,
77	      }));
78	      stop = true;
79	      return null;
80	    }
81	    const t = makeToken(kind, start, end, extra);
82	    tokens.push(t);
83	    return t;
84	  };
85	
86	  const makeToken = (kind: TokenKind, start: number, end: number, extra: Partial<Token>): Token => {
87	    const prev = start > 0 ? source[start - 1]! : '';
88	    const next = end < n ? source[end]! : '';
89	    const t: Token = {
90	      kind,
91	      text: source.slice(start, end),
92	      value: 0,
93	      name: '',
94	      line,
95	      col: start - lineStart + 1,
96	      start,
97	      end,
98	      spaceBefore: start === 0 || WS.test(prev),
99	      spaceAfter: end >= n || WS.test(next) || next === ';',
100	      firstOnLine: lastTokenLine !== line,
101	      lastOnLine: false,
102	      message: '',
103	      ...extra,
104	    };
105	    lastTokenLine = line;
106	    return t;
107	  };
108	
109	  while (i < n && !stop) {
110	    const c = source[i]!;
111	
112	    // Białe znaki i nowe linie.
113	    if (c === '\n') {
114	      i++;
115	      line++;
116	      lineStart = i;
117	      continue;
118	    }
119	    if (c === '\r') {
120	      i++;
121	      if (source[i] === '\n') i++;
122	      line++;
123	      lineStart = i;
124	      continue;
125	    }
126	    if (c === ' ' || c === '\t' || WS.test(c) || c === '﻿') {
127	      i++;
128	      continue;
129	    }
130	
131	    // Komentarz do końca wiersza.
132	    if (c === ';') {
133	      const s = i;
134	      while (i < n && source[i] !== '\n' && source[i] !== '\r') i++;
135	      comments.push([s, i]);
136	      continue;
137	    }
138	
139	    const start = i;
140	
141	    // Liczby: 80, 12.5, .5 — a wszystko inne, co zaczyna się jak liczba, jest błędem.
142	    if (isDigit(c) || (c === '.' && i + 1 < n && isDigit(source[i + 1]!))) {
143	      let j = i;
144	      while (j < n && isDigit(source[j]!)) j++;
145	      if (source[j] === '.' && j + 1 < n && isDigit(source[j + 1]!)) {
146	        j++;
147	        while (j < n && isDigit(source[j]!)) j++;
148	      }
149	      const after = j < n ? charAtCp(source, j) : '';
150	      if (after !== '' && (after === '.' || WORD_PART.test(after))) {
151	        // np. 1e3, 0x10, 5., 1.2.3, 10pw
152	        while (j < n) {
153	          const ch = charAtCp(source, j);
154	          if (ch === '.' || WORD_PART.test(ch)) j += ch.length;
155	          else break;
156	        }
157	        const raw = source.slice(start, j);
158	        push('err', start, j, {
159	          message: `Niepoprawna liczba „${raw}”. Liczby zapisujemy dziesiętnie, np. 80, 12.5 lub .5 (bez znaku, bez notacji wykładniczej).`,
160	        });
161	        i = j;
162	        continue;
163	      }
164	      const raw = source.slice(start, j);
165	      const value = Number(raw);
166	      if (!Number.isFinite(value)) {
167	        push('err', start, j, { message: `Liczba „${raw.length > 24 ? raw.slice(0, 24) + '…' : raw}” jest zbyt duża.` });
168	      } else {
169	        push('num', start, j, { value });
170	      }
171	      i = j;
172	      continue;
173	    }
174	
175	    // Słowa (nazwy i słowa kluczowe).
176	    const cp = charAtCp(source, i);
177	    if (WORD_START.test(cp)) {
178	      let j = i + cp.length;
179	      while (j < n) {
180	        const ch = charAtCp(source, j);
181	        if (WORD_PART.test(ch)) j += ch.length;
182	        else break;
183	      }
184	      push('word', start, j, { name: normalizeName(source.slice(start, j)) });
185	      i = j;
186	      continue;
187	    }
188	
189	    switch (c) {
190	      case '"': {
191	        let j = i + 1;
192	        while (j < n && source[j] !== '"' && source[j] !== '\n' && source[j] !== '\r') j++;
193	        if (j >= n || source[j] !== '"') {
194	          push('err', start, j, { message: 'Niezamknięty cudzysłów. Kolor zapisujemy tak: "#16866a".' });
195	          i = j;
196	        } else {
197	          push('str', start, j + 1);
198	          i = j + 1;
199	        }
200	        continue;
201	      }
202	      case ':': {
203	        const nextCh = i + 1 < n ? charAtCp(source, i + 1) : '';
204	        const prevIsWord = i > 0 && WORD_PART.test(charAtCp(source, i - 1)) ;
205	        if (nextCh !== '' && WORD_START.test(nextCh) && !prevIsWord) {
206	          let j = i + 1 + nextCh.length;
207	          while (j < n) {
208	            const ch = charAtCp(source, j);
209	            if (WORD_PART.test(ch)) j += ch.length;
210	            else break;
211	          }
212	          push('cname', start, j, { name: normalizeName(source.slice(i + 1, j)) });
213	          i = j;
214	        } else {
215	          push('colon', start, i + 1);
216	          i++;
217	        }
218	        continue;
219	      }
220	      case '+': case '-': case '*': case '/':
221	        push('op', start, i + 1);
222	        i++;
223	        continue;
224	      case '<':
225	        if (source[i + 1] === '=' || source[i + 1] === '>') {
226	          push('cmp', start, i + 2);
227	          i += 2;
228	        } else {
229	          push('cmp', start, i + 1);
230	          i++;
231	        }
232	        continue;
233	      case '>':
234	        if (source[i + 1] === '=') {
235	          push('cmp', start, i + 2);
236	          i += 2;
237	        } else {
238	          push('cmp', start, i + 1);
239	          i++;
240	        }
241	        continue;
242	      case '=':
243	        push('cmp', start, i + 1);
244	        i++;
245	        continue;
246	      case '[': push('lbr', start, i + 1); i++; continue;
247	      case ']': push('rbr', start, i + 1); i++; continue;
248	      case '(': push('lpar', start, i + 1); i++; continue;
249	      case ')': push('rpar', start, i + 1); i++; continue;
250	      case ',': push('comma', start, i + 1); i++; continue;
251	      default: {
252	        const bad = charAtCp(source, i);
253	        push('err', start, i + bad.length, { message: `Nieoczekiwany znak „${bad}”.` });
254	        i += bad.length;
255	        continue;
256	      }
257	    }
258	  }
259	
260	  // lastOnLine: ostatni symbol w wierszu.
261	  for (let k = 0; k < tokens.length; k++) {
262	    const t = tokens[k]!;
263	    const nx = tokens[k + 1];
264	    t.lastOnLine = !nx || nx.line !== t.line;
265	  }
266	
267	  return { tokens, comments };
268	}
269	
270	/** Pozycja (1-based) dla offsetu w źródle. */
271	export function positionOf(source: string, offset: number): { line: number; column: number } {
272	  let line = 1;
273	  let lineStart = 0;
274	  const end = Math.min(offset, source.length);
275	  for (let i = 0; i < end; i++) {
276	    const c = source[i];
277	    if (c === '\n') {
278	      line++;
279	      lineStart = i + 1;
280	    } else if (c === '\r') {
281	      if (source[i + 1] === '\n') i++;
282	      line++;
283	      lineStart = i + 1;
284	    }
285	  }
286	  return { line, column: offset - lineStart + 1 };
287	}
