1	import type { Cond, CompareOp, Expr, ExprOp, Mode, Proc, Program, Stmt } from './ast';
2	import { evalOps, EvalFail, repeatProblem, widthProblem } from './eval';
3	import { LogoError } from './errors';
4	import { COMMAND_BY_ID, isKeyword, KEYWORDS, type CommandId } from './keywords';
5	import { lex, positionOf, type Token } from './lexer';
6	import { LIMITS } from './limits';
7	
8	// ---------------------------------------------------------------------------
9	// Pomocnicze
10	
11	function describe(t: Token | undefined): string {
12	  if (!t) return 'koniec programu';
13	  switch (t.kind) {
14	    case 'num': return `liczbę ${t.text}`;
15	    case 'word': {
16	      const kw = KEYWORDS.get(t.name);
17	      if (kw?.kind === 'cmd') return `polecenie „${t.text}”`;
18	      if (kw) return `słowo „${t.text}”`;
19	      return `nazwę „${t.text}”`;
20	    }
21	    case 'cname': return `nazwę „${t.text}”`;
22	    case 'str': return `tekst ${t.text}`;
23	    case 'lbr': case 'rbr': case 'lpar': case 'rpar': return `nawias „${t.text}”`;
24	    case 'comma': return 'przecinek';
25	    case 'colon': return 'dwukropek';
26	    default: return `„${t.text}”`;
27	  }
28	}
29	
30	function plural(n: number, one: string, few: string, many: string): string {
31	  if (n === 1) return one;
32	  const m10 = n % 10;
33	  const m100 = n % 100;
34	  if (m10 >= 2 && m10 <= 4 && !(m100 >= 12 && m100 <= 14)) return few;
35	  return many;
36	}
37	
38	const CMD_HELP: Partial<Record<CommandId, string>> = {
39	  forward: 'ile kroków', back: 'ile kroków', right: 'ile stopni', left: 'ile stopni',
40	  pitchup: 'ile stopni', pitchdown: 'ile stopni', rollright: 'ile stopni', rollleft: 'ile stopni',
41	};
42	
43	// ---------------------------------------------------------------------------
44	// Nagłówki procedur (wspólne dla przebiegu wstępnego i właściwego)
45	
46	interface HeaderScan {
47	  nameTok?: Token;
48	  params: Token[];
49	  /** Indeks pierwszego symbolu po nagłówku. */
50	  endIdx: number;
51	  error?: { tok: Token; message: string };
52	}
53	
54	function scanHeader(tokens: Token[], idx: number): HeaderScan {
55	  const oto = tokens[idx]!;
56	  const same = (t: Token | undefined): t is Token => !!t && t.line === oto.line;
57	  const params: Token[] = [];
58	  let k = idx + 1;
59	  const fail = (tok: Token, message: string, nameTok?: Token): HeaderScan => ({ nameTok, params, endIdx: Math.max(k, idx + 1), error: { tok, message } });
60	
61	  const nameTok = tokens[k];
62	  if (!same(nameTok)) return fail(oto, 'Po „oto” brakuje nazwy procedury, np. „oto kwadrat ma: bok”.');
63	  if (nameTok.kind === 'err') return fail(nameTok, nameTok.message);
64	  if (nameTok.kind !== 'word') return fail(nameTok, `Nazwa procedury musi być słowem (litery, cyfry, znak _), a znaleziono ${describe(nameTok)}.`);
65	  if (isKeyword(nameTok.name)) return fail(nameTok, `„${nameTok.text}” jest słowem zarezerwowanym języka i nie może być nazwą procedury.`, nameTok);
66	  k++;
67	
68	  const addParam = (p: Token): HeaderScan | null => {
69	    if (p.kind === 'err') return fail(p, p.message, nameTok);
70	    if (p.kind !== 'word' && p.kind !== 'cname') return fail(p, `Nazwa parametru musi być słowem, a znaleziono ${describe(p)}.`, nameTok);
71	    if (isKeyword(p.name)) return fail(p, `„${p.text}” jest słowem zarezerwowanym języka i nie może być nazwą parametru.`, nameTok);
72	    if (params.some((q) => q.name === p.name)) return fail(p, `Parametr „${p.text.replace(/^:/, '')}” jest zadeklarowany dwa razy.`, nameTok);
73	    params.push(p);
74	    return null;
75	  };
76	
77	  const t = tokens[k];
78	  if (same(t)) {
79	    const nx = tokens[k + 1];
80	    if (t.kind === 'word' && t.name === 'ma' && same(nx) && (nx.kind === 'colon' || nx.kind === 'cname')) {
81	      // oto nazwa ma: a, b, c
82	      k++;
83	      if (tokens[k]!.kind === 'colon') k++;
84	      for (;;) {
85	        const p = tokens[k];
86	        if (!same(p)) return fail(tokens[k - 1]!, 'Brakuje nazwy parametru (lista parametrów: „ma: bok, kąt”).', nameTok);
87	        const bad = addParam(p);
88	        if (bad) return bad;
89	        k++;
90	        const c = tokens[k];
91	        if (same(c) && c.kind === 'comma') {
92	          k++;
93	          continue;
94	        }
95	        break;
96	      }
97	    } else if (t.kind === 'word' && t.name === 'ma') {
98	      return fail(t, 'Po „ma” oczekiwano dwukropka i listy parametrów: „ma: bok, kąt”.', nameTok);
99	    } else {
100	      // zapis dawny: oto nazwa :a :b
101	      while (same(tokens[k]) && tokens[k]!.kind === 'cname') {
102	        const bad = addParam(tokens[k]!);
103	        if (bad) return bad;
104	        k++;
105	      }
106	    }
107	    if (same(tokens[k])) {
108	      const bad = tokens[k]!;
109	      return fail(bad, bad.kind === 'err' ? bad.message : `Nieoczekiwany symbol w nagłówku procedury: ${describe(bad)}. Parametry zapisujemy tak: „ma: a, b”.`, nameTok);
110	    }
111	  }
112	  return { nameTok, params, endIdx: k };
113	}
114	
115	// ---------------------------------------------------------------------------
116	// Przebieg wstępny: nazwy procedur, ich parametry i zmienne zadeklarowane przez `niech`
117	
118	interface PreResult {
119	  procs: Map<string, Proc>;
120	  /** Proc zdefiniowany nagłówkiem zaczynającym się w tokenie o danym indeksie. */
121	  procAt: Map<number, Proc>;
122	  globals: Set<string>;
123	}
124	
125	function prepass(tokens: Token[]): PreResult {
126	  const procs = new Map<string, Proc>();
127	  const procAt = new Map<number, Proc>();
128	  const globals = new Set<string>();
129	  let cur: Proc | null = null;
130	
131	  for (let i = 0; i < tokens.length; i++) {
132	    const t = tokens[i]!;
133	    if (t.kind !== 'word') continue;
134	    const kw = KEYWORDS.get(t.name);
135	    if (!kw) continue;
136	    if (kw.kind === 'def' && t.firstOnLine && cur === null) {
137	      const h = scanHeader(tokens, i);
138	      const nm = h.nameTok;
139	      const proc: Proc = {
140	        name: nm && nm.kind === 'word' && !isKeyword(nm.name) ? nm.name : '',
141	        label: nm ? nm.text : '',
142	        params: h.params.map((p) => p.name),
143	        body: [],
144	        nameTok: nm ?? t,
145	        declared: new Set(h.params.map((p) => p.name)),
146	      };
147	      if (proc.name && !procs.has(proc.name)) procs.set(proc.name, proc);
148	      procAt.set(i, proc);
149	      cur = proc;
150	      i = h.endIdx - 1;
151	      continue;
152	    }
153	    if (kw.kind === 'end' && t.firstOnLine && t.lastOnLine && cur) {
154	      cur = null;
155	      continue;
156	    }
157	    if (kw.kind === 'cmd' && kw.id === 'let') {
158	      const nx = tokens[i + 1];
159	      if (nx && (nx.kind === 'word' || nx.kind === 'cname') && !isKeyword(nx.name)) {
160	        (cur ? cur.declared : globals).add(nx.name);
161	      }
162	    }
163	  }
164	  return { procs, procAt, globals };
165	}
166	
167	// ---------------------------------------------------------------------------
168	// Parser właściwy
169	
170	interface Ctx {
171	  proc: Proc | null;
172	  bracketDepth: number;
173	  repDepth: number;
174	}
175	
176	class Parser {
177	  private pos = 0;
178	  private ctx: Ctx = { proc: null, bracketDepth: 0, repDepth: 0 };
179	  private parenDepth = 0;
180	  private defined = new Map<string, Token>();
181	  private prev: Stmt | null = null;
182	
183	  constructor(
184	    private tokens: Token[],
185	    private mode: Mode,
186	    private pre: PreResult,
187	  ) {}
188	
189	  private peek(): Token | undefined {
190	    const t = this.tokens[this.pos];
191	    if (t && t.kind === 'err') throw this.err(t, t.message);
192	    return t;
193	  }
194	
195	  private err(t: Token, message: string): LogoError {
196	    return new LogoError(message, t.line, t.col, t.end - t.start);
197	  }
198	
199	  private fail(t: Token, message: string): never {
200	    throw this.err(t, message);
201	  }
202	
203	  parseProgram(): Program {
204	    const body: Stmt[] = [];
205	    for (;;) {
206	      const t = this.peek();
207	      if (!t) break;
208	      if (t.kind === 'word' && KEYWORDS.get(t.name)?.kind === 'def') {
209	        if (!t.firstOnLine) this.fail(t, `Definicja procedury („${t.text}”) musi zaczynać się na początku wiersza.`);
210	        this.procDef();
211	        continue;
212	      }
213	      body.push(this.statement());
214	    }
215	    return { mode: this.mode, body, procs: this.pre.procs, globals: this.pre.globals };
216	  }
217	
218	  // ----- procedury ------------------------------------------------------
219	
220	  private procDef(): void {
221	    const idx = this.pos;
222	    const oto = this.tokens[idx]!;
223	    const h = scanHeader(this.tokens, idx);
224	    if (h.error) this.fail(h.error.tok, h.error.message);
225	    const nameTok = h.nameTok!;
226	    const first = this.defined.get(nameTok.name);
227	    if (first) this.fail(nameTok, `Procedura „${nameTok.text}” jest już zdefiniowana (linia ${first.line}). Nazwę można zdefiniować tylko raz.`);
228	    this.defined.set(nameTok.name, nameTok);
229	    const proc = this.pre.procAt.get(idx)!;
230	    this.pos = h.endIdx;
231	
232	    const saved = this.ctx;
233	    this.ctx = { proc, bracketDepth: 0, repDepth: 0 };
234	    const body: Stmt[] = [];
235	    this.prev = null;
236	    for (;;) {
237	      const t = this.peek();
238	      if (!t) this.fail(oto, `Brakuje „już” kończącego procedurę „${nameTok.text}”.`);
239	      if (t.kind === 'word' && KEYWORDS.get(t.name)?.kind === 'end') {
240	        if (!(t.firstOnLine && t.lastOnLine)) this.fail(t, `„${t.text}” kończące procedurę musi stać samo w osobnym wierszu.`);
241	        this.pos++;
242	        break;
243	      }
244	      body.push(this.statement());
245	    }
246	    proc.body = body;
247	    this.ctx = saved;
248	    this.prev = null;
249	  }
250	
251	  // ----- instrukcje -----------------------------------------------------
252	
253	  private statement(): Stmt {
254	    const t = this.peek()!;
255	    const stmt = this.statement1(t);
256	    this.prev = stmt;
257	    return stmt;
258	  }
259	
260	  private statement1(t: Token): Stmt {
261	    if (t.kind !== 'word') this.stray(t);
262	    const kw = KEYWORDS.get(t.name);
263	    if (kw) {
264	      switch (kw.kind) {
265	        case 'cmd':
266	          return this.command(kw.id, t);
267	        case 'def':
268	          if (this.ctx.bracketDepth > 0) this.fail(t, 'Definicji procedury nie można umieszczać wewnątrz bloku [ … ] (powtórz, jeśli, jeżeli). Definiuj procedury na najwyższym poziomie programu.');
269	          if (this.ctx.proc) this.fail(t, `Definicji procedury nie można umieszczać wewnątrz innej procedury („${this.ctx.proc.label}”). Czy brakuje „już” kończącego poprzednią procedurę?`);
270	          this.fail(t, `Definicja procedury („${t.text}”) musi zaczynać się na początku wiersza.`);
271	          break;
272	        case 'end':
273	          if (this.ctx.proc || this.ctx.bracketDepth > 0) {
274	            if (!(t.firstOnLine && t.lastOnLine)) this.fail(t, `„${t.text}” kończące procedurę musi stać samo w osobnym wierszu.`);
275	          }
276	          this.fail(t, `Niepasujące „${t.text}” — nie ma otwartej procedury („oto …”).`);
277	          break;
278	        case 'repcount':
279	          this.fail(t, `„${t.text}” jest wartością (numer powtórzenia), a nie poleceniem. Użyj jej jako argumentu, np. „np ${t.text} * 5”.`);
280	      }
281	    }
282	    const proc = this.pre.procs.get(t.name);
283	    if (proc) return this.call(proc, t);
284	    if (this.isDeclared(t.name)) {
285	      this.fail(t, `„${t.text}” jest zmienną, a nie poleceniem. Aby ustawić zmienną, napisz „niech ${t.text} wartość”.`);
286	    }
287	    this.fail(t, `Nieznane polecenie „${t.text}”.`);
288	  }
289	
290	  private stray(t: Token): never {
291	    switch (t.kind) {
292	      case 'rbr': this.fail(t, 'Niepasujący nawias „]” — nie ma otwartego „[”.');
293	      case 'rpar': this.fail(t, 'Niepasujący nawias „)” — nie ma otwartego „(”.');
294	      case 'lbr': this.fail(t, 'Nieoczekiwany nawias „[”. Blok w nawiasach kwadratowych może występować tylko po powtórz, jeśli lub jeżeli.');
295	      case 'lpar': this.fail(t, 'Nieoczekiwany nawias „(”. Nawiasy okrągłe służą do grupowania wyrażeń, np. „np (2 + 3) * 4”.');
296	      case 'cmp': this.fail(t, `Nieoczekiwany znak „${t.text}”. Porównań używamy tylko w warunku po jeśli lub jeżeli.`);
297	      case 'comma': this.fail(t, 'Nieoczekiwany przecinek. Przecinki rozdzielają tylko parametry w nagłówku procedury.');
298	      case 'colon': this.fail(t, 'Nieoczekiwany dwukropek.');
299	      case 'op':
300	        this.fail(t, `Nieoczekiwany znak „${t.text}”. Operator łączący dwie wartości musi mieć odstępy po obu stronach albo po żadnej, np. „10 ${t.text} 5” lub „10${t.text}5”; zapis „10 ${t.text}5” to dwie osobne wartości.`);
301	      case 'str': this.fail(t, `Nieoczekiwany tekst ${t.text}. Tekst w cudzysłowie można podać tylko po poleceniu „kolor”.`);
302	      default: {
303	        const p = this.prev;
304	        let hint = '';
305	        if (p && p.t === 'call') {
306	          const n = p.proc.params.length;
307	          hint = ` Procedura „${p.proc.label}” przyjmuje ${n} ${plural(n, 'argument', 'argumenty', 'argumentów')}.`;
308	        } else if (p && p.t === 'cmd' && p.arg) {
309	          hint = ` Polecenie „${p.tok.text}” przyjmuje jeden argument.`;
310	        } else if (p && p.t === 'cmd') {
311	          hint = ` Polecenie „${p.tok.text}” nie przyjmuje argumentów.`;
312	        }
313	        this.fail(t, `Oczekiwano polecenia, a znaleziono ${describe(t)}.${hint}`);
314	      }
315	    }
316	  }
317	
318	  private command(id: CommandId, tok: Token): Stmt {
319	    const spec = COMMAND_BY_ID.get(id)!;
320	    if (spec.only3d && this.mode === '2d') {
321	      this.fail(tok, `Polecenie „${tok.text}” działa tylko w trybie 3D. W trybie 2D żółw porusza się po płaszczyźnie — przełącz tryb na 3D.`);
322	    }
323	    this.pos++;
324	    switch (id) {
325	      case 'forward': case 'back': case 'right': case 'left':
326	      case 'pitchup': case 'pitchdown': case 'rollright': case 'rollleft': {
327	        const arg = this.expr(tok, `Polecenie „${tok.text}” wymaga argumentu: ${CMD_HELP[id]} (liczby lub wyrażenia).`);
328	        return { t: 'cmd', id, arg, tok };
329	      }
330	      case 'penup': case 'pendown': case 'home': case 'clear': case 'stop':
331	        return { t: 'cmd', id, tok };
332	      case 'color': {
333	        const need = `Polecenie „${tok.text}” wymaga koloru w cudzysłowie, np. ${tok.text} "#16866a".`;
334	        const c = this.peek();
335	        if (!c) this.fail(tok, need);
336	        if (c.kind !== 'str') this.fail(c, `${need} Znaleziono ${describe(c)}.`);
337	        if (!/^"#[0-9a-fA-F]{6}"$/.test(c.text)) {
338	          this.fail(c, `Niepoprawny kolor ${c.text}. Kolor to znak # i sześć cyfr szesnastkowych, np. "#16866a".`);
339	        }
340	        this.pos++;
341	        return { t: 'color', hex: c.text.slice(1, -1).toLowerCase(), tok };
342	      }
343	      case 'width': {
344	        const arg = this.expr(tok, `Polecenie „${tok.text}” wymaga argumentu: grubości linii (liczby całkowitej od ${LIMITS.minWidth} do ${LIMITS.maxWidth}).`);
345	        if (arg.const !== undefined) {
346	          const p = widthProblem(arg.const);
347	          if (p) this.fail(arg.tok, p);
348	        }
349	        return { t: 'cmd', id: 'width', arg, tok };
350	      }
351	      case 'repeat': {
352	        const count = this.expr(tok, `Polecenie „${tok.text}” wymaga liczby powtórzeń, np. ${tok.text} 4 [ np 50 pw 90 ].`);
353	        if (count.const !== undefined) {
354	          const p = repeatProblem(count.const);
355	          if (p) this.fail(count.tok, p);
356	        }
357	        const body = this.block(tok, `Po liczbie powtórzeń oczekiwano nawiasu „[” z poleceniami do powtórzenia.`, true);
358	        return { t: 'repeat', count, body, tok };
359	      }
360	      case 'let': {
361	        const n = this.peek();
362	        if (!n) this.fail(tok, `Polecenie „${tok.text}” wymaga nazwy zmiennej i wartości, np. ${tok.text} x 5.`);
363	        if (n.kind !== 'word' && n.kind !== 'cname') this.fail(n, `Po „${tok.text}” oczekiwano nazwy zmiennej, a znaleziono ${describe(n)}.`);
364	        if (isKeyword(n.name)) this.fail(n, `„${n.text}” jest słowem zarezerwowanym języka i nie może być nazwą zmiennej.`);
365	        if (this.pre.procs.has(n.name)) this.fail(n, `„${n.text}” jest nazwą procedury i nie może być nazwą zmiennej.`);
366	        this.pos++;
367	        const expr = this.expr(tok, `Polecenie „${tok.text} ${n.text}” wymaga wartości (liczby lub wyrażenia).`);
368	        return { t: 'let', name: n.name, expr, tok };
369	      }
370	      case 'if': {
371	        const cond = this.cond(tok);
372	        const then = this.block(tok, `Po warunku oczekiwano nawiasu „[” z poleceniami.`, false);
373	        return { t: 'if', cond, then, tok };
374	      }
375	      case 'ifelse': {
376	        const cond = this.cond(tok);
377	        const then = this.block(tok, `Po warunku oczekiwano nawiasu „[” z poleceniami na „tak”.`, false);
378	        const els = this.block(tok, `Polecenie „${tok.text}” wymaga drugiego bloku [ … ] z poleceniami na „nie”.`, false);
379	        return { t: 'if', cond, then, else: els, tok };
380	      }
381	    }
382	  }
383	
384	  private cond(cmd: Token): Cond {
385	    const need = `Polecenie „${cmd.text}” wymaga warunku, np. ${cmd.text} x > 5 [ … ].`;
386	    const left = this.expr(cmd, need);
387	    const c = this.peek();
388	    if (!c) this.fail(cmd, `${need} Brakuje operatora porównania.`);
389	    if (c.kind !== 'cmp') {
390	      this.fail(c, `W warunku oczekiwano operatora porównania (<, >, =, <=, >=, <>), a znaleziono ${describe(c)}.`);
391	    }
392	    this.pos++;
393	    const right = this.expr(cmd, `Po operatorze „${c.text}” oczekiwano wartości do porównania.`);
394	    return { left, op: c.text as CompareOp, right };
395	  }
396	
397	  private block(cmd: Token, need: string, isRepeat: boolean): Stmt[] {
398	    const open = this.peek();
399	    if (!open) this.fail(cmd, need);
400	    if (open.kind !== 'lbr') this.fail(open, `${need} Znaleziono ${describe(open)}.`);
401	    if (this.ctx.bracketDepth >= LIMITS.maxBracketDepth) {
402	      this.fail(open, `Przekroczono limit zagnieżdżenia nawiasów [ ] (${LIMITS.maxBracketDepth}).`);
403	    }
404	    this.pos++;
405	    this.ctx.bracketDepth++;
406	    if (isRepeat) this.ctx.repDepth++;
407	    const stmts: Stmt[] = [];
408	    const unclosed = `Brakuje zamykającego nawiasu „]” dla tego „[”.`;
409	    for (;;) {
410	      const t = this.peek();
411	      if (!t) this.fail(open, unclosed);
412	      if (t.kind === 'rbr') {
413	        this.pos++;
414	        break;
415	      }
416	      if (t.kind === 'word' && KEYWORDS.get(t.name)?.kind === 'end' && t.firstOnLine && t.lastOnLine) this.fail(open, unclosed);
417	      stmts.push(this.statement());
418	    }
419	    this.ctx.bracketDepth--;
420	    if (isRepeat) this.ctx.repDepth--;
421	    return stmts;
422	  }
423	
424	  private call(proc: Proc, tok: Token): Stmt {
425	    this.pos++;
426	    const n = proc.params.length;
427	    const args: Expr[] = [];
428	    for (let i = 0; i < n; i++) {
429	      args.push(
430	        this.expr(
431	          tok,
432	          `Procedura „${proc.label}” przyjmuje ${n} ${plural(n, 'argument', 'argumenty', 'argumentów')}, a podano ${i}. Brakuje argumentu „${proc.params[i]}”.`,
433	        ),
434	      );
435	    }
436	    return { t: 'call', proc, args, tok };
437	  }
438	
439	  // ----- wyrażenia ------------------------------------------------------
440	
441	  private isDeclared(name: string): boolean {
442	    const p = this.ctx.proc;
443	    return (p !== null && p.declared.has(name)) || this.pre.globals.has(name);
444	  }
445	
446	  private expr(cmd: Token, need: string): Expr {
447	    const first = this.peek();
448	    if (!first) this.fail(cmd, need);
449	    const ops: ExprOp[] = [];
450	    this.additive(ops, cmd, need);
451	    const e: Expr = { ops, tok: first };
452	    if (!ops.some((o) => o.o === 'var' || o.o === 'rep')) {
453	      try {
454	        e.const = evalOps(ops, null);
455	      } catch (err) {
456	        if (!(err instanceof EvalFail)) throw err;
457	        // dzielenie przez zero itp. w stałym wyrażeniu: błąd wyjdzie w czasie wykonania
458	      }
459	    }
460	    return e;
461	  }
462	
463	  private binary(t: Token | undefined, chars: string): t is Token {
464	    return !!t && t.kind === 'op' && chars.includes(t.text) && t.spaceBefore === t.spaceAfter;
465	  }
466	
467	  private additive(ops: ExprOp[], cmd: Token, need: string): void {
468	    this.multiplicative(ops, cmd, need);
469	    for (;;) {
470	      const t = this.peek();
471	      if (!this.binary(t, '+-')) return;
472	      this.pos++;
473	      this.multiplicative(ops, cmd, need);
474	      ops.push({ o: t.text === '+' ? 'add' : 'sub' });
475	    }
476	  }
477	
478	  private multiplicative(ops: ExprOp[], cmd: Token, need: string): void {
479	    this.unary(ops, cmd, need);
480	    for (;;) {
481	      const t = this.peek();
482	      if (!this.binary(t, '*/')) return;
483	      this.pos++;
484	      this.unary(ops, cmd, need);
485	      ops.push({ o: t.text === '*' ? 'mul' : 'div' });
486	    }
487	  }
488	
489	  private unary(ops: ExprOp[], cmd: Token, need: string): void {
490	    let negs = 0;
491	    for (;;) {
492	      const t = this.peek();
493	      if (t && t.kind === 'op' && (t.text === '-' || t.text === '+')) {
494	        this.pos++;
495	        if (t.text === '-') negs++;
496	      } else break;
497	    }
498	    this.primary(ops, cmd, need);
499	    for (let i = 0; i < negs; i++) ops.push({ o: 'neg' });
500	  }
501	
502	  private primary(ops: ExprOp[], cmd: Token, need: string): void {
503	    const t = this.peek();
504	    if (!t) this.fail(cmd, need);
505	    switch (t.kind) {
506	      case 'num':
507	        this.pos++;
508	        ops.push({ o: 'num', v: t.value });
509	        return;
510	      case 'cname':
511	        this.pos++;
512	        this.checkVar(t);
513	        ops.push({ o: 'var', name: t.name });
514	        return;
515	      case 'word': {
516	        const kw = KEYWORDS.get(t.name);
517	        if (kw) {
518	          if (kw.kind === 'repcount') {
519	            if (this.ctx.repDepth === 0) {
520	              this.fail(t, `„${t.text}” można użyć tylko wewnątrz bloku powtórz (nie wystarczy, że procedura jest wywoływana z powtórz).`);
521	            }
522	            this.pos++;
523	            ops.push({ o: 'rep' });
524	            return;
525	          }
526	          this.fail(t, `${need} Znaleziono ${describe(t)}.`);
527	        }
528	        this.pos++;
529	        this.checkVar(t);
530	        ops.push({ o: 'var', name: t.name });
531	        return;
532	      }
533	      case 'lpar': {
534	        if (this.parenDepth >= LIMITS.maxParenDepth) {
535	          this.fail(t, `Zbyt głębokie zagnieżdżenie nawiasów okrągłych (limit ${LIMITS.maxParenDepth}).`);
536	        }
537	        this.pos++;
538	        this.parenDepth++;
539	        this.additive(ops, cmd, need);
540	        this.parenDepth--;
541	        const close = this.peek();
542	        if (!close || close.kind !== 'rpar') this.fail(t, 'Brakuje zamykającego nawiasu „)” dla tego „(”.');
543	        this.pos++;
544	        return;
545	      }
546	      default:
547	        this.fail(t, `${need} Znaleziono ${describe(t)}.`);
548	    }
549	  }
550	
551	  private checkVar(t: Token): void {
552	    if (this.isDeclared(t.name)) return;
553	    if (this.pre.procs.has(t.name)) {
554	      this.fail(t, `„${t.text}” jest nazwą procedury, a nie wartością. Procedury wywołujemy jak polecenia.`);
555	    }
556	    const hint = this.ctx.proc
557	      ? 'W wyrażeniu można użyć liczby, „nrpowt”, parametru procedury albo zmiennej ustawionej przez „niech”.'
558	      : 'W wyrażeniu można użyć liczby, „nrpowt” albo zmiennej ustawionej przez „niech”.';
559	    this.fail(t, `Nieznana nazwa „${t.text.replace(/^:/, '')}”. ${hint}`);
560	  }
561	}
