564	
565	export type ParseResult = { program: Program; error?: undefined } | { program?: undefined; error: LogoError };
566	
567	/** Analizuje cały program. Przy błędzie nic nie jest wykonywane. */
568	export function parse(source: string, mode: Mode): ParseResult {
569	  if (source.length > LIMITS.maxChars) {
570	    const pos = positionOf(source, LIMITS.maxChars);
571	    return {
572	      error: new LogoError(
573	        `Program jest zbyt długi: limit to ${LIMITS.maxChars.toLocaleString('pl-PL')} znaków.`,
574	        pos.line,
575	        pos.column,
576	        1,
577	      ),
578	    };
579	  }
580	  const { tokens } = lex(source);
581	  try {
582	    const pre = prepass(tokens);
583	    const program = new Parser(tokens, mode, pre).parseProgram();
584	    return { program };
585	  } catch (e) {
586	    if (e instanceof LogoError) return { error: e };
587	    if (e instanceof RangeError) {
588	      return { error: new LogoError('Program jest zbyt głęboko zagnieżdżony.', 1, 1, 1) };
589	    }
590	    throw e;
591	  }
592	}
