1	import type { Cond, Expr, Mode, Program, Stmt } from './ast';
2	import { EvalFail, evalOps, repeatProblem, widthProblem, type EvalEnv } from './eval';
3	import { LogoError } from './errors';
4	import { LIMITS } from './limits';
5	import { Turtle, type Segment, type Vec3 } from './turtle';
6	
7	export type StepKind = 'move' | 'turn' | 'pen' | 'style' | 'var' | 'repeat' | 'if' | 'call' | 'home' | 'clear' | 'stop';
8	
9	/** Jedna wykonana operacja — to, co widać przy wykonywaniu krok po kroku. */
10	export interface Step {
11	  kind: StepKind;
12	  line: number;
13	  col: number;
14	  len: number;
15	  /** Odcinek dodany tym krokiem. */
16	  seg?: Segment;
17	  cleared?: boolean;
18	  move?: { from: Vec3; to: Vec3 };
19	  rot?: { axis: 'yaw' | 'pitch' | 'roll'; deg: number };
20	  /** Czy `dom` zresetował orientację. */
21	  resetOrientation?: boolean;
22	  /** Względny „koszt czasowy” kroku przy animacji (0 = bez czekania). */
23	  cost: number;
24	}
25	
26	class Frame implements EvalEnv {
27	  reps: number[] = [];
28	  constructor(
29	    private globals: Map<string, number>,
30	    readonly locals: Map<string, number> | null,
31	  ) {}
32	
33	  lookup(name: string): number | undefined {
34	    if (this.locals) {
35	      const v = this.locals.get(name);
36	      if (v !== undefined) return v;
37	    }
38	    return this.globals.get(name);
39	  }
40	
41	  rep(): number {
42	    return this.reps[this.reps.length - 1]!;
43	  }
44	}
45	
46	function runError(message: string, tok: { line: number; col: number; start: number; end: number }): LogoError {
47	  return new LogoError(message, tok.line, tok.col, tok.end - tok.start, 'run');
48	}
