50	/** Maszyna wykonująca zweryfikowany program; krok po kroku (generator) albo w całości. */
51	export class Machine {
52	  readonly turtle = new Turtle();
53	  readonly segments: Segment[] = [];
54	  /** Zwiększane, gdy lista odcinków została wyczyszczona. */
55	  version = 0;
56	  ops = 0;
57	  error: LogoError | null = null;
58	  done = false;
59	
60	  private frames = 0;
61	  private globals = new Map<string, number>();
62	
63	  constructor(readonly program: Program) {}
64	
65	  get mode(): Mode {
66	    return this.program.mode;
67	  }
68	
69	  /** Wykonuje program krok po kroku. Błąd wykonania trafia do `error`. */
70	  *steps(): Generator<Step, void, void> {
71	    try {
72	      const top = new Frame(this.globals, null);
73	      yield* this.block(this.program.body, top);
74	    } catch (e) {
75	      if (e instanceof LogoError) this.error = e;
76	      else if (e instanceof RangeError) this.error = new LogoError('Przekroczono limit głębokości wykonania.', 1, 1, 1, 'run');
77	      else throw e;
78	    }
79	    this.done = true;
80	  }
81	
82	  /** Wykonuje do końca (bez animacji). */
83	  runToEnd(): void {
84	    for (const _ of this.steps()) void _;
85	  }
