87	  // ----- pomocnicze -----------------------------------------------------
88	
89	  private tick(tok: { line: number; col: number; start: number; end: number }): void {
90	    if (++this.ops > LIMITS.maxOps) {
91	      throw runError(`Przekroczono limit ${LIMITS.maxOps.toLocaleString('pl-PL')} wykonanych operacji (program działa zbyt długo).`, tok);
92	    }
93	  }
94	
95	  private value(e: Expr, f: Frame): number {
96	    if (e.const !== undefined) return e.const;
97	    try {
98	      return evalOps(e.ops, f);
99	    } catch (err) {
100	      if (err instanceof EvalFail) throw runError(err.message(), e.tok);
101	      throw err;
102	    }
103	  }
104	
105	  private holds(c: Cond, f: Frame): boolean {
106	    const a = this.value(c.left, f);
107	    const b = this.value(c.right, f);
108	    switch (c.op) {
109	      case '<': return a < b;
110	      case '>': return a > b;
111	      case '=': return a === b;
112	      case '<=': return a <= b;
113	      case '>=': return a >= b;
114	      default: return a !== b;
115	    }
116	  }
117	
118	  private addSegment(from: Vec3, to: Vec3, tok: { line: number; col: number; start: number; end: number }): Segment {
119	    if (this.segments.length >= LIMITS.maxSegments) {
120	      throw runError(`Przekroczono limit ${LIMITS.maxSegments.toLocaleString('pl-PL')} odcinków w rysunku.`, tok);
121	    }
122	    const seg: Segment = { from, to, color: this.turtle.color, width: this.turtle.width };
123	    this.segments.push(seg);
124	    return seg;
125	  }
126	
127	  private checkCoord(x: number, y: number, z: number, tok: { line: number; col: number; start: number; end: number }): void {
128	    const m = LIMITS.maxCoord;
129	    if (!(Math.abs(x) <= m && Math.abs(y) <= m && Math.abs(z) <= m)) {
130	      throw runError(`Żółw wyszedłby poza dozwolony obszar (współrzędne muszą mieścić się w zakresie ±${m.toLocaleString('pl-PL')}).`, tok);
131	    }
132	  }
133	
134	  private move(d: number, tok: Stmt['tok']): Step {
135	    const t = this.turtle;
136	    const nx = t.x + t.hx * d + 0;
137	    const ny = t.y + t.hy * d + 0;
138	    const nz = t.z + t.hz * d + 0;
139	    this.checkCoord(nx, ny, nz, tok);
140	    const from: Vec3 = [t.x, t.y, t.z];
141	    const to: Vec3 = [nx, ny, nz];
142	    let seg: Segment | undefined;
143	    const moved = nx !== t.x || ny !== t.y || nz !== t.z;
144	    if (moved && t.penDown) seg = this.addSegment(from, to, tok);
145	    t.x = nx; t.y = ny; t.z = nz;
146	    return step('move', tok, 1, { seg, move: { from, to } });
147	  }
148	
149	  // ----- wykonanie ------------------------------------------------------
150	
151	  private *block(stmts: Stmt[], f: Frame): Generator<Step, boolean, void> {
152	    for (let i = 0; i < stmts.length; i++) {
153	      if (yield* this.stmt(stmts[i]!, f)) return true;
154	    }
155	    return false;
156	  }
157	
158	  /** Zwraca `true`, jeśli wykonano `stop` (wyjście z procedury lub z programu). */
159	  private *stmt(s: Stmt, f: Frame): Generator<Step, boolean, void> {
160	    const t = this.turtle;
161	    switch (s.t) {
162	      case 'cmd': {
163	        this.tick(s.tok);
164	        switch (s.id) {
165	          case 'forward': yield this.move(this.value(s.arg!, f), s.tok); break;
166	          case 'back': yield this.move(-this.value(s.arg!, f), s.tok); break;
167	          case 'right': { const d = this.value(s.arg!, f); t.yaw(d); yield step('turn', s.tok, 1, { rot: { axis: 'yaw', deg: d } }); break; }
168	          case 'left': { const d = -this.value(s.arg!, f); t.yaw(d); yield step('turn', s.tok, 1, { rot: { axis: 'yaw', deg: d } }); break; }
169	          case 'pitchup': { const d = this.value(s.arg!, f); t.pitch(d); yield step('turn', s.tok, 1, { rot: { axis: 'pitch', deg: d } }); break; }
170	          case 'pitchdown': { const d = -this.value(s.arg!, f); t.pitch(d); yield step('turn', s.tok, 1, { rot: { axis: 'pitch', deg: d } }); break; }
171	          case 'rollright': { const d = this.value(s.arg!, f); t.roll(d); yield step('turn', s.tok, 1, { rot: { axis: 'roll', deg: d } }); break; }
172	          case 'rollleft': { const d = -this.value(s.arg!, f); t.roll(d); yield step('turn', s.tok, 1, { rot: { axis: 'roll', deg: d } }); break; }
173	          case 'penup': t.penDown = false; yield step('pen', s.tok, 0.3); break;
174	          case 'pendown': t.penDown = true; yield step('pen', s.tok, 0.3); break;
175	          case 'width': {
176	            const w = this.value(s.arg!, f);
177	            const p = widthProblem(w);
178	            if (p) throw runError(p, s.arg!.tok);
179	            t.width = w;
180	            yield step('style', s.tok, 0.3);
181	            break;
182	          }
183	          case 'home': {
184	            const from: Vec3 = [t.x, t.y, t.z];
185	            const to: Vec3 = [0, 0, 0];
186	            let seg: Segment | undefined;
187	            if (t.penDown && (t.x !== 0 || t.y !== 0 || t.z !== 0)) seg = this.addSegment(from, to, s.tok);
188	            t.resetOrientation();
189	            yield step('home', s.tok, 1, { seg, move: { from, to }, resetOrientation: true });
190	            break;
191	          }
192	          case 'clear':
193	            this.segments.length = 0;
194	            this.version++;
195	            yield step('clear', s.tok, 0.3, { cleared: true });
196	            break;
197	          case 'stop':
198	            yield step('stop', s.tok, 0.3);
199	            return true;
200	        }
201	        return false;
202	      }
203	      case 'color':
204	        this.tick(s.tok);
205	        t.color = s.hex;
206	        yield step('style', s.tok, 0.3);
207	        return false;
208	      case 'let': {
209	        this.tick(s.tok);
210	        const v = this.value(s.expr, f);
211	        if (f.locals) f.locals.set(s.name, v);
212	        else this.globals.set(s.name, v);
213	        yield step('var', s.tok, 0.2);
214	        return false;
215	      }
216	      case 'repeat': {
217	        this.tick(s.tok);
218	        const n = this.value(s.count, f);
219	        const p = repeatProblem(n);
220	        if (p) throw runError(p, s.count.tok);
221	        yield step('repeat', s.tok, 0.2);
222	        if (n === 0) return false;
223	        if (this.frames >= LIMITS.maxFrames) {
224	          throw runError(`Przekroczono limit ${LIMITS.maxFrames} jednocześnie aktywnych wywołań procedur i powtórzeń.`, s.tok);
225	        }
226	        this.frames++;
227	        f.reps.push(0);
228	        for (let i = 1; i <= n; i++) {
229	          f.reps[f.reps.length - 1] = i;
230	          if (yield* this.block(s.body, f)) {
231	            f.reps.pop();
232	            this.frames--;
233	            return true;
234	          }
235	          this.tick(s.tok);
236	        }
237	        f.reps.pop();
238	        this.frames--;
239	        return false;
240	      }
241	      case 'if': {
242	        this.tick(s.tok);
243	        const yes = this.holds(s.cond, f);
244	        yield step('if', s.tok, 0.2);
245	        const body = yes ? s.then : s.else;
246	        if (!body) return false;
247	        if (yield* this.block(body, f)) return true;
248	        this.tick(s.tok);
249	        return false;
250	      }
251	      case 'call': {
252	        this.tick(s.tok);
253	        const locals = new Map<string, number>();
254	        const params = s.proc.params;
255	        for (let i = 0; i < params.length; i++) locals.set(params[i]!, this.value(s.args[i]!, f));
256	        if (this.frames >= LIMITS.maxFrames) {
257	          throw runError(
258	            `Przekroczono limit ${LIMITS.maxFrames} jednocześnie aktywnych wywołań procedur i powtórzeń (zbyt głęboka rekurencja?).`,
259	            s.tok,
260	          );
261	        }
262	        this.frames++;
263	        yield step('call', s.tok, 0.2);
264	        yield* this.block(s.proc.body, new Frame(this.globals, locals));
265	        this.frames--;
266	        this.tick(s.tok);
267	        return false;
268	      }
269	    }
270	  }
271	}
272	
273	function step(kind: StepKind, tok: { line: number; col: number; start: number; end: number }, cost: number, extra: Partial<Step> = {}): Step {
274	  return { kind, line: tok.line, col: tok.col, len: tok.end - tok.start, cost, ...extra };
275	}
