1	import type { ExprOp } from './ast';
2	import { LIMITS } from './limits';
3	
4	/** Środowisko obliczania wyrażeń. */
5	export interface EvalEnv {
6	  lookup(name: string): number | undefined;
7	  rep(): number;
8	}
9	
10	export type EvalFailKind = 'div0' | 'nonfinite' | 'unassigned';
11	
12	export class EvalFail {
13	  constructor(public kind: EvalFailKind, public name = '') {}
14	
15	  message(): string {
16	    switch (this.kind) {
17	      case 'div0':
18	        return 'Dzielenie przez zero.';
19	      case 'nonfinite':
20	        return 'Wynik obliczenia nie jest skończoną liczbą (przekroczono zakres liczb).';
21	      default:
22	        return `Zmienna „${this.name}” nie ma jeszcze wartości — użyj najpierw „niech ${this.name} …”.`;
23	    }
24	  }
25	}
26	
27	/** Oblicza wyrażenie zapisane w odwrotnej notacji polskiej. Zgłasza `EvalFail`. */
28	export function evalOps(ops: ExprOp[], env: EvalEnv | null): number {
29	  const st: number[] = [];
30	  for (let i = 0; i < ops.length; i++) {
31	    const op = ops[i]!;
32	    switch (op.o) {
33	      case 'num':
34	        st.push(op.v);
35	        break;
36	      case 'var': {
37	        const v = env ? env.lookup(op.name) : undefined;
38	        if (v === undefined) throw new EvalFail('unassigned', op.name);
39	        st.push(v);
40	        break;
41	      }
42	      case 'rep':
43	        st.push(env ? env.rep() : 0);
44	        break;
45	      case 'neg':
46	        st.push(-st.pop()!);
47	        break;
48	      default: {
49	        const b = st.pop()!;
50	        const a = st.pop()!;
51	        let r: number;
52	        if (op.o === 'add') r = a + b;
53	        else if (op.o === 'sub') r = a - b;
54	        else if (op.o === 'mul') r = a * b;
55	        else {
56	          if (b === 0) throw new EvalFail('div0');
57	          r = a / b;
58	        }
59	        if (!Number.isFinite(r)) throw new EvalFail('nonfinite');
60	        st.push(r);
61	      }
62	    }
63	  }
64	  return st[st.length - 1]!;
65	}
66	
67	/** Komunikat o niepoprawnej grubości albo `null`. */
68	export function widthProblem(v: number): string | null {
69	  if (Number.isInteger(v) && v >= LIMITS.minWidth && v <= LIMITS.maxWidth) return null;
70	  return `Grubość musi być liczbą całkowitą od ${LIMITS.minWidth} do ${LIMITS.maxWidth} (otrzymano ${fmt(v)}).`;
71	}
72	
73	/** Komunikat o niepoprawnej liczbie powtórzeń albo `null`. */
74	export function repeatProblem(v: number): string | null {
75	  if (Number.isInteger(v) && v >= 0 && v <= LIMITS.maxRepeat) return null;
76	  return `Liczba powtórzeń musi być liczbą całkowitą od 0 do ${LIMITS.maxRepeat.toLocaleString('pl-PL')} (otrzymano ${fmt(v)}).`;
77	}
78	
79	export function fmt(v: number): string {
80	  if (Number.isInteger(v)) return String(v);
81	  const s = Number(v.toPrecision(10)).toString();
82	  return s.replace('.', ',');
83	}
