60	export const KEYWORDS: Map<string, KeywordInfo> = (() => {
61	  const m = new Map<string, KeywordInfo>();
62	  for (const c of COMMANDS) for (const n of [...c.pl, ...c.en]) m.set(normalizeName(n), { kind: 'cmd', id: c.id });
63	  for (const n of DEF_WORDS) m.set(n, { kind: 'def' });
64	  for (const n of END_WORDS) m.set(normalizeName(n), { kind: 'end' });
65	  for (const n of REPCOUNT_WORDS) m.set(n, { kind: 'repcount' });
