1	/** Żółw w przestrzeni: położenie oraz trzy wersory (kierunek, prawa strona, góra). */
2	
3	export interface Segment {
4	  from: [number, number, number];
5	  to: [number, number, number];
6	  color: string;
7	  width: number;
8	}
9	
10	export type Vec3 = [number, number, number];
11	
12	export interface Pose {
13	  pos: Vec3;
14	  /** Kierunek ruchu (nos). */
15	  h: Vec3;
16	  /** Prawa strona. */
17	  r: Vec3;
18	  /** Góra żółwia. */
19	  u: Vec3;
20	  penDown: boolean;
21	  color: string;
22	  width: number;
23	}
24	
25	export const DEFAULT_COLOR = '#16866a';
26	export const DEFAULT_WIDTH = 3;
27	
28	/** Sinus i cosinus kąta w stopniach; wielokrotności 90° są dokładne. */
29	export function sinCosDeg(deg: number): [number, number] {
30	  let a = deg % 360;
31	  if (a < 0) a += 360;
32	  if (a === 0) return [0, 1];
33	  if (a === 90) return [1, 0];
34	  if (a === 180) return [0, -1];
35	  if (a === 270) return [-1, 0];
36	  const r = (a * Math.PI) / 180;
37	  return [Math.sin(r), Math.cos(r)];
38	}
39	
40	export class Turtle {
41	  x = 0; y = 0; z = 0;
42	  hx = 0; hy = 1; hz = 0;
43	  rx = 1; ry = 0; rz = 0;
44	  ux = 0; uy = 0; uz = 1;
45	  penDown = true;
46	  color = DEFAULT_COLOR;
47	  width = DEFAULT_WIDTH;
48	
49	  /** Przywraca położenie początkowe i orientację (pióro, kolor i grubość bez zmian). */
50	  resetOrientation(): void {
51	    this.x = 0; this.y = 0; this.z = 0;
52	    this.hx = 0; this.hy = 1; this.hz = 0;
53	    this.rx = 1; this.ry = 0; this.rz = 0;
54	    this.ux = 0; this.uy = 0; this.uz = 1;
55	  }
56	
57	  /** Obrót w prawo (wokół wektora „góra”) o `deg` stopni. */
58	  yaw(deg: number): void {
59	    const [s, c] = sinCosDeg(deg);
60	    const { hx, hy, hz, rx, ry, rz } = this;
61	    this.hx = hx * c + rx * s; this.hy = hy * c + ry * s; this.hz = hz * c + rz * s;
62	    this.rx = rx * c - hx * s; this.ry = ry * c - hy * s; this.rz = rz * c - hz * s;
63	  }
64	
65	  /** Uniesienie nosa (wokół wektora „prawo”) o `deg` stopni. */
66	  pitch(deg: number): void {
67	    const [s, c] = sinCosDeg(deg);
68	    const { hx, hy, hz, ux, uy, uz } = this;
69	    this.hx = hx * c + ux * s; this.hy = hy * c + uy * s; this.hz = hz * c + uz * s;
70	    this.ux = ux * c - hx * s; this.uy = uy * c - hy * s; this.uz = uz * c - hz * s;
71	  }
72	
73	  /** Przechył w prawo (wokół kierunku ruchu) o `deg` stopni. */
74	  roll(deg: number): void {
75	    const [s, c] = sinCosDeg(deg);
76	    const { rx, ry, rz, ux, uy, uz } = this;
77	    this.ux = ux * c + rx * s; this.uy = uy * c + ry * s; this.uz = uz * c + rz * s;
78	    this.rx = rx * c - ux * s; this.ry = ry * c - uy * s; this.rz = rz * c - uz * s;
79	  }
80	
81	  pose(): Pose {
82	    return {
83	      pos: [this.x, this.y, this.z],
84	      h: [this.hx, this.hy, this.hz],
85	      r: [this.rx, this.ry, this.rz],
86	      u: [this.ux, this.uy, this.uz],
87	      penDown: this.penDown,
88	      color: this.color,
89	      width: this.width,
90	    };
91	  }
92	}
93	
94	export function initialPose(): Pose {
95	  return new Turtle().pose();
96	}
97	
98	/** Obrót pozy o `deg` stopni — do animacji obrotów żółwia. */
99	export function rotatePose(p: Pose, axis: 'yaw' | 'pitch' | 'roll', deg: number): Pose {
100	  const t = new Turtle();
101	  [t.x, t.y, t.z] = p.pos;
102	  [t.hx, t.hy, t.hz] = p.h;
103	  [t.rx, t.ry, t.rz] = p.r;
104	  [t.ux, t.uy, t.uz] = p.u;
105	  t.penDown = p.penDown; t.color = p.color; t.width = p.width;
106	  if (axis === 'yaw') t.yaw(deg);
107	  else if (axis === 'pitch') t.pitch(deg);
108	  else t.roll(deg);
109	  return t.pose();
110	}
