1	import type { CommandId } from './keywords';
2	import type { Token } from './lexer';
3	
4	export type Mode = '2d' | '3d';
5	
6	/** Wyrażenie skompilowane do postaci odwrotnej notacji polskiej (bez rekurencji przy obliczaniu). */
7	export type ExprOp =
8	  | { o: 'num'; v: number }
9	  | { o: 'var'; name: string }
10	  | { o: 'rep' }
11	  | { o: 'neg' }
12	  | { o: 'add' }
13	  | { o: 'sub' }
14	  | { o: 'mul' }
15	  | { o: 'div' };
16	
17	export interface Expr {
18	  ops: ExprOp[];
19	  /** Pierwszy symbol wyrażenia — tu zgłaszane są błędy wartości. */
20	  tok: Token;
21	  /** Wartość, jeśli wyrażenie nie zależy od nazw i da się je policzyć w czasie analizy. */
22	  const?: number;
