  return r as { segments: Seg[]; error: null | { message: string; line: number; column: number }; ms: number; threw?: string };
}
const near = (a: number[], b: number[]) => a.length === b.length && a.every((v, i) => Math.abs(v - b[i]!) < 1e-9);
let fails = 0, total = 0;
export function fmtSeg(s: Seg) { return `(${s.from.map(n=>+n.toFixed(6)).join(',')})->(${s.to.map(n=>+n.toFixed(6)).join(',')}) ${s.color} w${s.width}`; }
// expect: segs as [x1,y1,z1,x2,y2,z2], err as [line,col] or null (no error) or 'any'
export function t(name: string, src: string, mode: '2d' | '3d', segs: number[][] | null, err: [number, number] | null | 'any', extra?: { color?: string; width?: number }) {
  total++;
  const r = run(src, mode);
  const probs: string[] = [];
  if (r.threw) probs.push('THREW ' + r.threw.split('\n')[0]);
  else {
    if (err === null && r.error) probs.push(`unexpected error ${r.error.line}:${r.error.column} ${r.error.message}`);
    else if (err === 'any' && !r.error) probs.push('expected an error, got none');
    else if (Array.isArray(err)) {
      if (!r.error) probs.push(`expected error at ${err}, got none`);
      else if (r.error.line !== err[0] || r.error.column !== err[1]) probs.push(`error pos ${r.error.line}:${r.error.column} (want ${err}) msg=${r.error.message}`);
    }
    if (r.error && !r.error.message) probs.push('empty message');
    if (segs) {
      const got = r.segments.map(s => [...s.from, ...s.to]);
      if (got.length !== segs.length || !got.every((g, i) => near(g, segs[i]!))) probs.push(`segments got ${JSON.stringify(got.map(g=>g.map(n=>+n.toFixed(6))))} want ${JSON.stringify(segs)}`);
    }
    if (extra?.color && r.segments.some(s => s.color !== extra.color)) probs.push('colour ' + r.segments.map(s=>s.color));
    if (extra?.width && r.segments.some(s => s.width !== extra.width)) probs.push('width ' + r.segments.map(s=>s.width));
    if (r.ms > 1000) probs.push(`slow ${r.ms.toFixed(0)}ms`);
  }
  if (probs.length) { fails++; console.log(`FAIL ${name}: ${JSON.stringify(src).slice(0, 120)}\n     ${probs.join('\n     ')}`); }
}
export function done() { console.log(`${total - fails}/${total} as-expected; ${fails} mismatch`); }
export function show(label: string, src: string, mode: '2d' | '3d' = '2d') {
  const r = run(src, mode);
  if (r.threw) { console.log(`## ${label}: THREW ${r.threw.split('\n')[0]}`); return r; }
  console.log(`## ${label}: ${JSON.stringify(src.length > 100 ? src.slice(0, 100) + '...' : src)}  [${mode}] ${r.ms.toFixed(0)}ms\n   segs=${r.segments.length} ${r.segments.slice(0, 6).map(fmtSeg).join(' | ')}\n   err=${r.error ? `${r.error.line}:${r.error.column} ${r.error.message}` : 'null'}`);
  return r;
}
