import { t, done, show, run } from './h.ts';
const F = (d: number) => [[0,0,0,0,d,0]];
function ops(src: string, mode: '2d'|'3d' = '2d') { const r = run(src, mode); return r.error ? `ERR ${r.error.line}:${r.error.column} ${r.error.message.slice(0,60)}` : 'ok'; }
// find exact op count behaviour: programs with N ops -> ok/err
function probe(label: string, mk: (n: number) => string, expectPerUnit: number, base: number) {
  // mk(n) program; compute expected ops = base + n*expectPerUnit; test boundary
  const lim = 10000;
  const nOk = Math.floor((lim - base) / expectPerUnit);
  const rOk = ops(mk(nOk)); const rBad = ops(mk(nOk + 1));
  console.log(label, `n=${nOk} ->`, rOk, `| n=${nOk+1} ->`, rBad);
}
// straight commands: n copies of "np 1" limited by 10000 tokens => max 5000. Use dom? use procedure calls to scale.
// repeat with body np: 1 + n*(1+1) 
probe('repeat np body (1+2n)', n => `powtorz ${n} [np 0]`, 2, 1);
probe('repeat nested empty', n => `powtorz ${n} []`, 1, 1);
// repeat 100 of repeat n [np 0]: 1 + 100*(1 + 2n + 1) = 201 + 200n
probe('nested repeat', n => `powtorz 100 [powtorz ${n} [np 0]]`, 200, 201);
// call: proc f with body np 0: call=1, np=1, finish=1 -> 3 per call
probe('call', n => `oto f\n np 0\njuż\npowtorz ${n} [f]`, 5, 1); // each iter: call(1)+np(1)+callfinish(1)+iterfinish(1) = 4 ... compute
EOF
