3	import { EXAMPLES } from '../data/examples';
4	import { anyDialogOpen } from './dialog';
5	import { shortcutsDialog } from './dialogs';
6	import { clear, h, icon, nextFrame, turtleLogo, type IconName } from './dom';
7	import { hrefFor, parseHash, replaceHash, type Route } from './router';
8	import { decodeProgram, readPermalink } from './share';
9	import { matchShortcut } from './shortcuts';
10	import { Drafts, Settings } from './store';
11	import { applyTheme, cycleTheme, THEME_LABEL } from './theme';
12	import { toast } from './toast';
13	import { Workspace } from './workspace';
14	import { ChallengesPage } from './pages/challenges';
15	import { ExamplesPage } from './pages/examples';
16	import { ReferencePage } from './pages/reference';
17	
18	export interface Page {
19	  el: HTMLElement;
20	  /** Wywoływane przy każdym wejściu na stronę. */
21	  enter?(route: Route): void;
22	  leave?(): void;
23	  title(route: Route): string;
24	  /** Aktywny obszar roboczy (skróty klawiszowe). */
25	  workspace?(): Workspace | null;
26	}
27	
28	const NAV: Array<{ id: string; label: string; icon: IconName; href: string }> = [
29	  { id: 'pracownia', label: 'Pracownia', icon: 'pencil', href: hrefFor([]) },
30	  { id: 'przyklady', label: 'Przykłady', icon: 'grid', href: hrefFor(['przyklady']) },
31	  { id: 'wyzwania', label: 'Wyzwania', icon: 'star', href: hrefFor(['wyzwania']) },
32	  { id: 'polecenia', label: 'Polecenia', icon: 'book', href: hrefFor(['polecenia']) },
33	];
34	
35	export class App {
36	  readonly studio: Workspace;
37	  private main: HTMLElement;
38	  private navLinks = new Map<string, HTMLAnchorElement>();
39	  private pages = new Map<string, Page>();
40	  private current: { id: string; page: Page } | null = null;
41	  private themeBtn!: HTMLButtonElement;
42	  private ready: Promise<void>;
43	  private initialRun = false;
44	  private resolveReady!: () => void;
45	
46	  constructor(private root: HTMLElement) {
47	    this.ready = new Promise((res) => (this.resolveReady = res));
48	    this.studio = new Workspace({
49	      initialMode: Settings.mode,
50	      modeSwitch: true,
51	      examples: true,
52	      ariaLabel: 'Edytor programu Logo',
53	      load: (m) => Drafts.get(m) ?? defaultSource(m),
54	      persist: (m, t) => Drafts.set(m, t),
55	    });
56	    this.main = h('main', { id: 'main', class: 'main', tabindex: '-1' });
57	    this.build();
58	    window.addEventListener('hashchange', () => void this.route());
59	    document.addEventListener('keydown', (e) => this.onKey(e));
60	  }
61	
62	  private build(): void {
63	    const brand = h(
64	      'a',
65	      { class: 'brand', href: hrefFor([]), 'aria-label': 'Logomocja — strona główna (pracownia)' },
66	      h('span', { class: 'brand-mark' }, turtleLogo(30)),
67	      h('span', { class: 'brand-name' }, 'Logomocja'),
68	    );
69	    const nav = h('nav', { class: 'mainnav', 'aria-label': 'Główne' });
70	    for (const n of NAV) {
71	      const a = h('a', { class: 'navlink', href: n.href, 'data-nav': n.id }, icon(n.icon, 20), h('span', null, n.label));
72	      this.navLinks.set(n.id, a);
73	      nav.append(a);
74	    }
75	    this.themeBtn = h('button', { class: 'icon-btn', type: 'button', onclick: () => this.onTheme() });
76	    const keys = h('button', { class: 'icon-btn', type: 'button', title: 'Skróty klawiszowe', 'aria-label': 'Skróty klawiszowe', onclick: () => shortcutsDialog() }, icon('keyboard', 20));
77	    const actions = h('div', { class: 'appbar-actions' }, keys, this.themeBtn);
78	    const skip = h('a', { class: 'skip-link', href: '#main', onclick: (e: Event) => { e.preventDefault(); this.main.focus(); } }, 'Przejdź do treści');
79	    const header = h('header', { class: 'appbar' }, brand, nav, actions);
80	    this.root.append(skip, header, this.main);
81	    this.updateThemeBtn();
82	  }
83	
84	  private onTheme(): void {
85	    const next = cycleTheme();
86	    this.updateThemeBtn();
87	    toast(`Motyw: ${THEME_LABEL[next]}.`);
88	  }
89	
90	  private updateThemeBtn(): void {
91	    const pref = Settings.theme;
92	    const label = `Motyw: ${THEME_LABEL[pref]}. Kliknij, aby zmienić.`;
93	    this.themeBtn.setAttribute('aria-label', label);
94	    this.themeBtn.title = label;
95	    this.themeBtn.replaceChildren(icon(pref === 'dark' ? 'moon' : pref === 'light' ? 'sun' : 'auto', 20));
96	  }
97	
98	  // ----- trasy ----------------------------------------------------------
99	
100	  private getPage(id: string): Page {
101	    let p = this.pages.get(id);
102	    if (p) return p;
103	    switch (id) {
104	      case 'przyklady': p = new ExamplesPage(this); break;
105	      case 'wyzwania': p = new ChallengesPage(this); break;
106	      case 'polecenia': p = new ReferencePage(this); break;
107	      default: p = new StudioPage(this); break;
108	    }
109	    this.pages.set(id, p);
110	    return p;
111	  }
112	
113	  async start(): Promise<void> {
114	    applyTheme();
115	    await this.route(true);
116	    if (!this.initialRun) {
117	      this.initialRun = true;
118	      await nextFrame();
119	      this.studio.init();
120	    }
121	    this.resolveReady();
122	  }
123	
124	  async route(initial = false): Promise<void> {
125	    const route = parseHash();
126	    const shared = readPermalink(route);
127	    if (shared) {
128	      await this.openShared(shared.payload, shared.mode);
129	      return;
130	    }
131	    const first = route.path[0] ?? '';
132	    const id = ['przyklady', 'wyzwania', 'polecenia'].includes(first) ? first : 'pracownia';
133	    const page = this.getPage(id);
134	    if (this.current && this.current.id !== id) this.current.page.leave?.();
135	    if (!this.current || this.current.id !== id) {
136	      clear(this.main);
137	      this.main.append(page.el);
138	      this.current = { id, page };
139	    }
140	    page.enter?.(route);
141	    for (const [k, a] of this.navLinks) {
142	      if (k === id) a.setAttribute('aria-current', 'page');
143	      else a.removeAttribute('aria-current');
144	    }
145	    document.title = `${page.title(route)} — Logomocja`;
146	    if (!initial) this.main.scrollTop = 0;
147	    if (id === 'pracownia') {
148	      // widok mógł być ukryty — dopasuj po pokazaniu
149	      await nextFrame();
150	      this.studio.getView().paintNow();
151	    }
152	  }
153	
154	  /** Otwiera program z adresu (link do udostępniania). */
155	  private async openShared(payload: string, mode: Mode): Promise<void> {
156	    try {
157	      const source = await decodeProgram(payload);
158	      // adres „zużywamy”: dalsze edycje nie są nadpisywane przy odświeżeniu
159	      replaceHash(hrefFor([]));
160	      this.goStudio();
161	      this.studio.replaceSource(source, { mode, run: true, title: 'link' });
162	      toast('Wczytano program z linku i uruchomiono go.', { kind: 'ok' });
163	    } catch (e) {
164	      replaceHash(hrefFor([]));
165	      this.goStudio();
166	      toast(e instanceof Error ? `Nie udało się odczytać linku: ${e.message}` : 'Nie udało się odczytać linku.', { kind: 'error' });
167	    }
168	  }
169	
170	  private goStudio(): void {
171	    const page = this.getPage('pracownia');
172	    if (this.current && this.current.id !== 'pracownia') this.current.page.leave?.();
173	    if (!this.current || this.current.id !== 'pracownia') {
174	      clear(this.main);
175	      this.main.append(page.el);
176	      this.current = { id: 'pracownia', page };
177	    }
178	    page.enter?.({ path: [], query: new URLSearchParams() });
179	    for (const [k, a] of this.navLinks) {
180	      if (k === 'pracownia') a.setAttribute('aria-current', 'page');
181	      else a.removeAttribute('aria-current');
182	    }
183	    document.title = 'Pracownia — Logomocja';
184	  }
185	
186	  /** Ładuje program do pracowni (np. z przykładu lub strony poleceń). */
187	  openInStudio(source: string, mode: Mode, opts: { title?: string; run?: boolean } = {}): void {
188	    this.goStudio();
189	    replaceHash(hrefFor([]));
190	    this.studio.replaceSource(source, { mode, title: opts.title ?? null, run: opts.run !== false });
191	    void nextFrame().then(() => this.studio.focusEditor());
192	  }
193	
194	  loadExampleInStudio(id: string): void {
195	    this.goStudio();
196	    replaceHash(hrefFor([]));
197	    this.studio.loadExample(id);
198	  }
199	
200	  /**
201	   * Interfejs testowy: wczytuje kod do edytora (jak wklejony), wykonuje go do końca
202	   * bez animacji, dopasowuje widok i czeka na namalowanie rysunku.
203	   */
204	  async open(source: string, mode: Mode): Promise<{ segments: Segment[]; error: { message: string; line: number; column: number } | null }> {
205	    await this.ready;
206	    this.goStudio();
207	    replaceHash(hrefFor([]));
208	    const ws = this.studio;
209	    ws.runner.reset();
210	    if (ws.mode !== mode) ws.setMode(mode, { text: source, run: false });
211	    else {
212	      ws.editor.setValue(source);
213	      Drafts.set(mode, source);
214	    }
215	    ws.title = null;
216	    ws.runInstant();
217	    await ws.settled();
218	    // wynik z czystego interpretera — ten sam, który widać na ekranie
219	    return runSource(source, mode);
220	  }
221	
222	  // ----- skróty ---------------------------------------------------------
223	
224	  private activeWorkspace(): Workspace | null {
225	    return this.current?.page.workspace?.() ?? null;
226	  }
227	
228	  private onKey(e: KeyboardEvent): void {
229	    if (anyDialogOpen()) return;
230	    const id = matchShortcut(e);
231	    if (!id) return;
232	    const t = e.target as HTMLElement | null;
233	    const typing = !!t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable);
234	    const inEditor = !!t && t.classList?.contains('editor-input');
235	    if (id === 'help') {
236	      if (typing) return;
237	      e.preventDefault();
238	      shortcutsDialog();
239	      return;
240	    }
241	    const ws = this.activeWorkspace();
242	    if (!ws) return;
243	    // Esc w polach formularzy (poza edytorem) zostaje dla przeglądarki
244	    if (id === 'reset' && typing && !inEditor) return;
245	    e.preventDefault();
246	    switch (id) {
247	      case 'run': ws.run(); break;
248	      case 'step': ws.step(); break;
249	      case 'pause': ws.togglePause(); break;
250	      case 'reset': ws.reset(); break;
251	      case 'save': ws.download(); break;
252	    }
253	  }
254	}
