1	/** Skróty klawiszowe — jedno źródło prawdy dla obsługi i listy w interfejsie. */
2	
3	export type ShortcutId = 'run' | 'step' | 'pause' | 'reset' | 'save' | 'help' | 'fit';
4	
5	export interface Shortcut {
6	  id: ShortcutId;
7	  keys: string[];
8	  label: string;
9	  /** Skrót działa także, gdy fokus jest w edytorze. */
10	  inEditor: boolean;
11	}
12	
13	export const SHORTCUTS: Shortcut[] = [
14	  { id: 'run', keys: ['Ctrl+Enter', 'F9'], label: 'Uruchom program od początku', inEditor: true },
15	  { id: 'step', keys: ['Ctrl+Shift+Enter', 'F10'], label: 'Wykonaj jeden krok (polecenie po poleceniu)', inEditor: true },
16	  { id: 'pause', keys: ['Ctrl+.', 'F8'], label: 'Wstrzymaj albo wznów wykonanie', inEditor: true },
17	  { id: 'reset', keys: ['Esc'], label: 'Zatrzymaj, wyczyść rysunek i ustaw żółwia na początku', inEditor: true },
18	  { id: 'save', keys: ['Ctrl+S'], label: 'Pobierz program jako plik .logo', inEditor: true },
19	  { id: 'help', keys: ['?'], label: 'Pokaż listę skrótów (poza edytorem)', inEditor: false },
20	];
21	
22	export const CANVAS_KEYS: Array<{ keys: string; label: string }> = [
23	  { keys: 'Strzałki', label: 'Przesuwanie widoku (2D) lub obracanie kamery (3D)' },
24	  { keys: 'Shift + strzałki', label: 'Przesuwanie widoku' },
25	  { keys: '+ / −', label: 'Przybliżanie i oddalanie' },
26	  { keys: '0 lub Home', label: 'Dopasowanie widoku do rysunku' },
27	];
28	
29	export const MOUSE_HINTS: Array<{ keys: string; label: string }> = [
30	  { keys: 'Przeciąganie', label: '2D: przesuwanie widoku · 3D: obracanie kamery' },
31	  { keys: 'Shift / prawy przycisk + przeciąganie', label: 'Przesuwanie widoku' },
32	  { keys: 'Kółko myszy · szczypanie', label: 'Przybliżanie i oddalanie' },
33	  { keys: 'Dwukrotne kliknięcie', label: 'Dopasowanie widoku do rysunku' },
34	];
35	
36	export function matchShortcut(e: KeyboardEvent): ShortcutId | null {
37	  const mod = e.ctrlKey || e.metaKey;
38	  if (e.altKey) return null;
39	  const k = e.key;
40	  if (mod && k === 'Enter') return e.shiftKey ? 'step' : 'run';
41	  if (mod && !e.shiftKey && (k === '.' || e.code === 'Period')) return 'pause';
42	  if (mod && !e.shiftKey && (k === 's' || k === 'S')) return 'save';
43	  if (!mod && !e.shiftKey && k === 'F9') return 'run';
44	  if (!mod && !e.shiftKey && k === 'F10') return 'step';
45	  if (!mod && !e.shiftKey && k === 'F8') return 'pause';
46	  if (!mod && !e.shiftKey && k === 'Escape') return 'reset';
47	  if (!mod && k === '?') return 'help';
48	  return null;
49	}
50	
51	export function isMac(): boolean {
52	  return typeof navigator !== 'undefined' && /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
53	}
54	
55	/** Zapis skrótu do wyświetlenia (Ctrl → ⌘ na komputerach Apple). */
56	export function showKeys(keys: string): string {
57	  return isMac() ? keys.replace('Ctrl+', '⌘+') : keys;
58	}
59	
60	export function tooltip(label: string, id: ShortcutId): string {
61	  const s = SHORTCUTS.find((x) => x.id === id)!;
62	  return `${label} (${s.keys.map(showKeys).join(' lub ')})`;
63	}
