160	  private applySplit(ratio: number): void {
161	    const r = Math.min(0.7, Math.max(0.25, ratio));
162	    this.el.style.setProperty('--code-w', `${(r * 100).toFixed(2)}%`);
163	    this.splitter?.setAttribute('aria-valuenow', String(Math.round(r * 100)));
164	    Settings.split = r;
165	  }
166	
167	  private buildSplitter(split: HTMLElement): HTMLElement {
168	    const el = h('div', {
169	      class: 'splitter',
170	      role: 'separator',
171	      tabindex: '0',
172	      'aria-orientation': 'vertical',
173	      'aria-label': 'Szerokość edytora i rysunku',
174	      'aria-valuemin': '25',
175	      'aria-valuemax': '70',
176	      'aria-valuenow': '42',
177	      title: 'Przeciągnij, aby zmienić szerokość edytora (lub użyj strzałek)',
178	    });
179	    let dragging = false;
180	    const move = (clientX: number) => {
181	      const rect = split.getBoundingClientRect();
182	      this.applySplit((clientX - rect.left) / rect.width);
183	    };
184	    el.addEventListener('pointerdown', (e) => {
185	      dragging = true;
186	      el.setPointerCapture(e.pointerId);
187	      el.classList.add('dragging');
188	      e.preventDefault();
189	    });
190	    el.addEventListener('pointermove', (e) => {
191	      if (dragging) move(e.clientX);
192	    });
193	    const end = (e: PointerEvent) => {
194	      dragging = false;
195	      el.classList.remove('dragging');
196	      if (el.hasPointerCapture(e.pointerId)) el.releasePointerCapture(e.pointerId);
197	    };
198	    el.addEventListener('pointerup', end);
199	    el.addEventListener('pointercancel', end);
200	    el.addEventListener('dblclick', () => this.applySplit(0.42));
201	    el.addEventListener('keydown', (e) => {
202	      const step = e.shiftKey ? 0.08 : 0.02;
203	      if (e.key === 'ArrowLeft') this.applySplit(Settings.split - step);
204	      else if (e.key === 'ArrowRight') this.applySplit(Settings.split + step);
205	      else if (e.key === 'Home') this.applySplit(0.25);
206	      else if (e.key === 'End') this.applySplit(0.7);
207	      else return;
208	      e.preventDefault();
209	    });
210	    return el;
211	  }
