213	  /** Przeciągnięcie pliku .logo na obszar roboczy otwiera go. */
214	  private bindDrop(): void {
215	    const hasFiles = (e: DragEvent) => !!e.dataTransfer && [...e.dataTransfer.types].includes('Files');
216	    let depth = 0;
217	    this.el.addEventListener('dragenter', (e) => {
218	      if (!hasFiles(e)) return;
219	      e.preventDefault();
220	      depth++;
221	      this.el.classList.add('drop-target');
222	    });
223	    this.el.addEventListener('dragover', (e) => {
224	      if (hasFiles(e)) e.preventDefault();
225	    });
226	    this.el.addEventListener('dragleave', () => {
227	      depth = Math.max(0, depth - 1);
228	      if (depth === 0) this.el.classList.remove('drop-target');
229	    });
230	    this.el.addEventListener('drop', (e) => {
231	      if (!hasFiles(e)) return;
232	      e.preventDefault();
233	      depth = 0;
234	      this.el.classList.remove('drop-target');
235	      const f = e.dataTransfer?.files?.[0];
236	      if (f) void this.openFile(f);
237	    });
238	  }
