557	  /** Sprawdza program w tle i pokazuje ewentualny błąd składni bez rysowania. */
558	  private liveValidate(): void {
559	    if (this.disposed || this.runState === 'running' || this.runState === 'paused') return;
560	    const text = this.editor.value;
561	    const r = parse(text, this.mode);
562	    if (r.error) {
563	      this.currentError = r.error;
564	      this.editor.setError({ line: r.error.line, column: r.error.column, length: r.error.length, message: r.error.message, phase: 'parse' });
565	      this.showErrorStatus(r.error);
566	    } else if (this.currentError) {
567	      this.currentError = null;
568	      this.editor.setError(null);
569	      this.setStatus(text.trim() ? 'Program wygląda poprawnie — uruchom go (Ctrl+Enter).' : 'Gotowe do uruchomienia.');
570	    }
571	  }
