574	
575	  setMode(mode: Mode, opts: { run?: boolean; text?: string } = {}): void {
576	    if (mode === this.mode && opts.text === undefined) {
577	      this.syncModeInputs();
578	      return;
579	    }
580	    this.validate.cancel();
581	    this.runner.reset();
582	    this.currentError = null;
583	    this.editor.setError(null);
584	    this.mode = mode;
585	    Settings.mode = mode;
586	    this.title = null;
587	    this.syncModeInputs();
588	    this.switchView(mode);
589	    this.updateHint();
590	    const text = opts.text ?? this.opts.load(mode);
591	    this.editor.setValue(text);
592	    if (opts.text !== undefined) this.opts.persist(mode, text);
593	    this.opts.onMode?.(mode);
594	    if (opts.run !== false && text.trim()) this.runInstant();
595	    else this.liveValidate();
596	  }
