598	  private syncModeInputs(): void {
599	    for (const m of ['2d', '3d'] as const) {
600	      const i = this.modeInputs[m];
601	      if (i) i.checked = m === this.mode;
602	    }
603	  }
604	
605	  // ----- zastępowanie kodu (z zachowaniem szkicu) -----------------------
606	
607	  /** Tekst, który zostałby utracony przy wczytaniu czegoś w trybie `target`. */
608	  private atRisk(target: Mode): string {
609	    if (target === this.mode) return this.editor.value;
610	    return this.opts.load(target);
611	  }
612	
613	  /**
614	   * Wczytuje kod do edytora. Jeśli zastępuje niezapisany szkic użytkownika,
615	   * szkic trafia do „Szkiców” i można go od razu przywrócić.
616	   */
617	  replaceSource(text: string, o: ReplaceOptions = {}): void {
618	    const target = this.opts.modeSwitch ? (o.mode ?? this.mode) : this.mode;
619	    const prev = this.atRisk(target);
620	    let undo: (() => void) | null = null;
621	    if (o.stash !== false && prev !== text && isUserDraft(prev, target, this.opts.pristine?.() ?? [])) {
622	      const entry = Stash.add(target, prev);
623	      this.refreshStashCount();
624	      const prevTitle = this.title;
625	      undo = () => {
626	        Stash.remove(entry.id);
627	        this.refreshStashCount();
628	        this.replaceSource(prev, { mode: target, stash: false, run: true, quiet: true, title: prevTitle });
629	      };
630	    }
631	    if (target !== this.mode) {
632	      this.setMode(target, { text, run: o.run !== false });
633	      this.title = o.title ?? null;
634	    } else {
635	      this.title = o.title ?? null;
636	      this.validate.cancel();
637	      this.runner.reset();
638	      this.currentError = null;
639	      this.editor.setError(null);
640	      this.editor.setValue(text);
641	      this.opts.persist(this.mode, text);
642	      if (o.run !== false) this.runInstant();
643	      else this.liveValidate();
644	    }
645	    this.opts.onEdit?.();
646	    if (undo && !o.quiet) {
647	      toast('Poprzedni szkic został zachowany w „Szkicach”.', { actionLabel: 'Cofnij', onAction: undo });
648	    }
649	  }
650	
651	  loadExample(id: string): void {
652	    const ex = findExample(id);
653	    if (!ex) return;
654	    this.replaceSource(ex.source, { mode: ex.mode, title: ex.id, run: true });
655	    this.focusEditor();
656	    toast(`Wczytano przykład „${ex.name}” (${ex.mode.toUpperCase()}).`, { kind: 'ok' });
657	  }
658	
659	  refreshStashCount(): void {
660	    const n = Stash.list().length;
661	    this.stashCount.textContent = n ? String(n) : '';
662	    this.stashCount.classList.toggle('on', n > 0);
663	  }
664	
665	  // ----- pliki, obraz, link --------------------------------------------
666	
667	  download(): void {
668	    downloadProgram(this.editor.value, programFileName(this.mode, this.title ?? 'logomocja'));
669	    toast('Program został pobrany jako plik .logo.', { kind: 'ok' });
670	  }
671	
672	  private async onFilePicked(): Promise<void> {
673	    const f = this.fileInput.files?.[0];
674	    this.fileInput.value = '';
675	    if (!f) return;
676	    await this.openFile(f);
677	  }
678	
679	  async openFile(f: File): Promise<void> {
680	    try {
681	      const text = await readTextFile(f);
682	      const mode = this.opts.modeSwitch ? guessMode(f.name, text, this.mode) : this.mode;
683	      this.replaceSource(text, { mode, title: slug(f.name.replace(/\.[^.]+$/, '')), run: true });
684	      toast(`Otwarto plik „${f.name}”.`, { kind: 'ok' });
685	    } catch (e) {
686	      toast(e instanceof Error ? e.message : 'Nie udało się otworzyć pliku.', { kind: 'error' });
687	    }
688	  }
689	
690	  async exportPng(): Promise<void> {
691	    try {
692	      this.view.paintNow();
693	      const blob = await this.view.exportPng();
694	      downloadBlob(blob, `${slug(this.title ?? 'rysunek')}-${this.mode}.png`);
695	      toast('Rysunek zapisano jako obraz PNG.', { kind: 'ok' });
696	    } catch (e) {
697	      toast(e instanceof Error ? e.message : 'Nie udało się zapisać obrazu.', { kind: 'error' });
698	    }
699	  }
700	
701	  async share(): Promise<void> {
702	    await shareDialog(this.mode, this.editor.value);
703	  }
704	
705	  // ----- sterowanie z zewnątrz -----------------------------------------
706	
707	  /** Pierwsze narysowanie szkicu po zbudowaniu strony. */
708	  init(): void {
709	    if (this.editor.value.trim()) this.runInstant();
710	    else this.liveValidate();
711	  }
712	
713	  /** Czeka na namalowanie rysunku (do testów i zrzutów ekranu). */
714	  async settled(): Promise<void> {
715	    await nextFrame();
716	    this.view.paintNow();
717	    await nextFrame();
718	  }
719	
720	  dispose(): void {
721	    this.disposed = true;
722	    this.runner.dispose();
723	    this.validate.cancel();
724	    this.editor.dispose();
725	    for (const v of Object.values(this.views)) v?.dispose();
726	  }
727	
728	}
