1	import { h } from './dom';
2	import { escapeHtml, highlight, runsToHtml, type Run } from './highlight';
3	
4	export interface ErrorMark {
5	  line: number;
6	  column: number;
7	  length: number;
8	  message: string;
9	  /** `parse` — błąd wykryty przed rysowaniem; `run` — w trakcie wykonania. */
10	  phase?: 'parse' | 'run';
11	}
12	
13	export interface EditorOptions {
14	  ariaLabel: string;
15	  placeholder?: string;
16	  onInput?: (text: string) => void;
17	  onCaret?: (line: number, column: number) => void;
18	}
19	
20	/** Edytor: textarea z nałożoną warstwą podświetlania, numerami wierszy i znacznikami. */
21	export class Editor {
22	  readonly el: HTMLElement;
23	  readonly textarea: HTMLTextAreaElement;
24	  private scroller: HTMLElement;
25	  private overlay: HTMLElement;
26	  private gutter: HTMLElement;
27	  private error: ErrorMark | null = null;
28	  private activeLine: number | null = null;
29	  private lines: Run[][] = [];
30	  private raf = 0;
31	  private lastText = '';
32	  private metrics: { lh: number; cw: number; padTop: number; padLeft: number } | null = null;
33	  private pendingReveal = false;
34	  private ro: ResizeObserver | null = null;
35	
36	  constructor(private opts: EditorOptions) {
37	    this.textarea = h('textarea', {
38	      class: 'editor-input',
39	      spellcheck: 'false',
40	      autocapitalize: 'off',
41	      autocomplete: 'off',
42	      autocorrect: 'off',
43	      wrap: 'off',
44	      'aria-label': opts.ariaLabel,
45	      placeholder: opts.placeholder ?? '',
46	      rows: 1,
47	    });
48	    this.overlay = h('pre', { class: 'editor-overlay', 'aria-hidden': 'true' });
49	    this.gutter = h('div', { class: 'editor-gutter', 'aria-hidden': 'true' });
50	    const wrap = h('div', { class: 'editor-code' }, this.overlay, this.textarea);
51	    this.scroller = h('div', { class: 'editor-scroll' }, h('div', { class: 'editor-inner' }, this.gutter, wrap));
52	    this.el = h('div', { class: 'editor' }, this.scroller);
53	
54	    this.textarea.addEventListener('input', () => {
55	      this.refresh(true);
56	      opts.onInput?.(this.textarea.value);
57	    });
58	    this.textarea.addEventListener('scroll', () => {
59	      this.textarea.scrollTop = 0;
60	      this.textarea.scrollLeft = 0;
61	    });
62	    const caret = () => this.reportCaret();
63	    this.textarea.addEventListener('keyup', caret);
64	    this.textarea.addEventListener('click', caret);
65	    this.textarea.addEventListener('focus', caret);
66	    this.textarea.addEventListener('keydown', (e) => {
67	      if (e.key.startsWith('Arrow') || e.key === 'Home' || e.key === 'End' || e.key === 'PageUp' || e.key === 'PageDown') {
68	        requestAnimationFrame(() => this.revealCaret());
69	      }
70	    });
71	    // Kliknięcie w pusty obszar edytora ustawia fokus w polu tekstowym.
72	    this.scroller.addEventListener('mousedown', (e) => {
73	      if (e.target === this.scroller || (e.target as HTMLElement).classList?.contains('editor-inner')) {
74	        e.preventDefault();
75	        this.textarea.focus();
76	      }
77	    });
78	    this.dirtyText = true;
79	    this.render();
80	    if (typeof ResizeObserver === 'function') {
81	      this.ro = new ResizeObserver(() => {
82	        this.metrics = null;
83	      });
84	      this.ro.observe(this.el);
85	    }
86	    void document.fonts?.ready?.then(() => {
87	      this.metrics = null;
88	    });
89	  }
90	
91	  get value(): string {
92	    return this.textarea.value;
93	  }
94	
95	  setValue(text: string, silent = true): void {
96	    this.textarea.value = text;
97	    this.dirtyText = true;
98	    this.render();
99	    this.scroller.scrollTop = 0;
100	    this.scroller.scrollLeft = 0;
101	    if (!silent) this.opts.onInput?.(text);
102	  }
103	
104	  focus(): void {
105	    this.textarea.focus({ preventScroll: true });
106	  }
107	
108	  setError(err: ErrorMark | null): void {
109	    this.error = err;
110	    this.scheduleRender();
111	  }
112	
113	  setActiveLine(line: number | null, reveal = true): void {
114	    if (this.activeLine === line) return;
115	    this.activeLine = line;
116	    this.scheduleRender();
117	    if (line !== null && reveal) this.revealLine(line);
118	  }
119	
120	  setReadOnly(ro: boolean): void {
121	    this.textarea.readOnly = ro;
122	  }
123	
124	  /** Zaznacza błędny fragment i przenosi do niego fokus. */
125	  selectError(): void {
126	    const e = this.error;
127	    if (!e) return;
128	    const starts = this.lineStarts();
129	    const ls = starts[e.line - 1] ?? 0;
130	    const from = ls + e.column - 1;
131	    this.textarea.focus({ preventScroll: true });
132	    this.textarea.setSelectionRange(from, from + Math.max(1, e.length));
133	    this.revealLine(e.line);
134	    this.revealCaret();
135	  }
136	
137	  // ----- wnętrze --------------------------------------------------------
138	
139	  private lineStarts(): number[] {
140	    const text = this.textarea.value;
141	    const starts = [0];
142	    for (let i = 0; i < text.length; i++) {
143	      const c = text.charCodeAt(i);
144	      if (c === 10) starts.push(i + 1);
145	      else if (c === 13) {
146	        if (text.charCodeAt(i + 1) === 10) i++;
147	        starts.push(i + 1);
148	      }
149	    }
150	    return starts;
151	  }
152	
153	  private reportCaret(): void {
154	    if (!this.opts.onCaret) return;
155	    const pos = this.textarea.selectionStart;
156	    const starts = this.lineStarts();
157	    let line = 0;
158	    while (line + 1 < starts.length && starts[line + 1]! <= pos) line++;
159	    this.opts.onCaret(line + 1, pos - starts[line]! + 1);
160	  }
161	
162	  private measure(): { lh: number; cw: number; padTop: number; padLeft: number } {
163	    if (this.metrics) return this.metrics;
164	    const cs = getComputedStyle(this.textarea);
165	    const lh = parseFloat(cs.lineHeight) || 22;
166	    const probe = h('span', { class: 'editor-probe' }, '0000000000');
167	    this.overlay.appendChild(probe);
168	    const cw = probe.getBoundingClientRect().width / 10 || 8;
169	    probe.remove();
170	    this.metrics = { lh, cw, padTop: parseFloat(cs.paddingTop) || 0, padLeft: parseFloat(cs.paddingLeft) || 0 };
171	    return this.metrics;
172	  }
173	
174	  private revealLine(line: number): void {
175	    const { lh, padTop } = this.measure();
176	    const top = padTop + (line - 1) * lh;
177	    const view = this.scroller.clientHeight;
178	    const st = this.scroller.scrollTop;
179	    if (top < st + lh) this.scroller.scrollTop = Math.max(0, top - lh * 2);
180	    else if (top + lh * 2 > st + view) this.scroller.scrollTop = top + lh * 3 - view;
181	  }
182	
183	  /** Zapewnia widoczność karetki (przy dopisywaniu na końcu długich wierszy lub dokumentu). */
184	  private revealCaret(): void {
185	    if (document.activeElement !== this.textarea) return;
186	    const pos = this.textarea.selectionStart;
187	    const starts = this.lineStarts();
188	    let line = 0;
189	    while (line + 1 < starts.length && starts[line + 1]! <= pos) line++;
190	    const col = pos - starts[line]!;
191	    const { lh, cw, padTop, padLeft } = this.measure();
192	    const gutterW = this.gutter.offsetWidth;
193	    const top = padTop + line * lh;
194	    const left = gutterW + padLeft + col * cw;
195	    const s = this.scroller;
196	    if (top < s.scrollTop) s.scrollTop = top;
197	    else if (top + lh + 4 > s.scrollTop + s.clientHeight) s.scrollTop = top + lh + 4 - s.clientHeight;
198	    if (left - gutterW < s.scrollLeft) s.scrollLeft = Math.max(0, left - gutterW - 30);
199	    else if (left + cw * 2 > s.scrollLeft + s.clientWidth) s.scrollLeft = left + cw * 4 - s.clientWidth;
200	  }
201	
202	  private scheduleRender(): void {
203	    if (this.raf) return;
204	    this.raf = requestAnimationFrame(() => {
205	      this.raf = 0;
206	      this.render();
207	      if (this.pendingReveal) {
208	        this.pendingReveal = false;
209	        this.revealCaret();
210	      }
211	    });
212	  }
213	
214	  private dirtyText = true;
215	
216	  /** Przelicza podświetlenie po zmianie tekstu (scalane do jednej klatki animacji). */
217	  private refresh(revealCaret = false): void {
218	    this.dirtyText = true;
219	    if (revealCaret) this.pendingReveal = true;
220	    this.scheduleRender();
221	  }
222	
223	  private render(): void {
224	    if (this.dirtyText) {
225	      this.dirtyText = false;
226	      const text = this.textarea.value;
227	      this.lastText = text;
228	      this.lines = highlight(text);
229	    }
230	    const e = this.error;
231	    const parts: string[] = [];
232	    const nums: string[] = [];
233	    for (let i = 0; i < this.lines.length; i++) {
234	      const lineNo = i + 1;
235	      const isErr = !!e && e.line === lineNo;
236	      const isActive = this.activeLine === lineNo;
237	      let html: string;
238	      if (isErr && e) html = runsToHtml(markRuns(this.lines[i]!, e.column - 1, e.column - 1 + Math.max(1, e.length)));
239	      else html = runsToHtml(this.lines[i]!);
240	      let msg = '';
241	      if (isErr && e) {
242	        const m = e.message.length > 120 ? e.message.slice(0, 119) + '…' : e.message;
243	        msg = `<span class="ln-msg" data-phase="${e.phase ?? 'parse'}">${escapeHtml(m)}</span>`;
244	      }
245	      parts.push(`<div class="ln${isActive ? ' ln-active' : ''}${isErr ? ' ln-err' : ''}">${html}${msg}</div>`);
246	      nums.push(`<div class="gl${isActive ? ' gl-active' : ''}${isErr ? ' gl-err' : ''}">${lineNo}</div>`);
247	    }
248	    this.overlay.innerHTML = parts.join('');
249	    this.gutter.innerHTML = nums.join('');
250	    this.gutter.style.setProperty('--digits', String(String(this.lines.length).length));
251	  }
252	
253	  dispose(): void {
254	    if (this.raf) cancelAnimationFrame(this.raf);
255	    this.ro?.disconnect();
256	  }
257	
258	  get text(): string {
259	    return this.lastText;
260	  }
261	}
262	
263	/** Zaznacza zakres kolumn [from, to) w wierszu fragmentów. */
264	function markRuns(runs: Run[], from: number, to: number): Run[] {
265	  const out: Run[] = [];
266	  let pos = 0;
267	  for (const r of runs) {
268	    const s = pos;
269	    const e = pos + r.text.length;
270	    pos = e;
271	    if (e <= from || s >= to) {
272	      out.push(r);
273	      continue;
274	    }
275	    const a = Math.max(from, s) - s;
276	    const b = Math.min(to, e) - s;
277	    if (a > 0) out.push({ ...r, text: r.text.slice(0, a) });
278	    out.push({ ...r, text: r.text.slice(a, b), cls: `${r.cls} mk-err`.trim() });
279	    if (b < r.text.length) out.push({ ...r, text: r.text.slice(b) });
280	  }
281	  // Błąd poza końcem wiersza (np. brak argumentu na końcu): pokaż znacznik na końcu.
282	  if (from >= pos) out.push({ text: ' ', cls: 'mk-err' });
283	  return out;
284	}
