1	import { Machine, parse, rotatePose, initialPose, type LogoError, type Mode, type Pose, type Program, type Segment, type Step } from '../lang';
2	import type { Scene } from './view/common';
3	import { prefersReducedMotion } from './dom';
4	
5	export type RunState = 'idle' | 'running' | 'paused' | 'finished';
6	
7	/** Poziomy szybkości animacji: operacje na sekundę (Infinity = bez animacji). */
8	export const SPEEDS: Array<{ label: string; ops: number; maxSeconds: number }> = [
9	  { label: 'Bardzo wolno', ops: 2.5, maxSeconds: Infinity },
10	  { label: 'Wolno', ops: 7, maxSeconds: 60 },
11	  { label: 'Normalnie', ops: 22, maxSeconds: 20 },
12	  { label: 'Szybko', ops: 90, maxSeconds: 5 },
13	  { label: 'Bardzo szybko', ops: 600, maxSeconds: 1.5 },
14	  { label: 'Natychmiast', ops: Infinity, maxSeconds: 0 },
15	];
16	
17	export interface RunnerSink {
18	  scene(scene: Scene): void;
19	  line(line: number | null): void;
20	  state(state: RunState): void;
21	  /** Błąd analizy (przed rysowaniem) albo wykonania. */
22	  error(err: LogoError | null): void;
23	  /** Wykonanie zakończone (także błędem wykonania). */
24	  finished(info: { segments: Segment[]; error: LogoError | null; ops: number; animated: boolean }): void;
25	  /** Wiadomość dla paska stanu. */
26	  message(text: string): void;
27	}
28	
29	interface Anim {
30	  step: Step;
31	  before: Pose;
32	  after: Pose;
33	  elapsed: number;
34	  dur: number;
35	}
36	
37	const TWEEN_MIN_DUR = 1 / 40;
38	
39	/** Steruje wykonaniem programu: uruchamianie, kroki, pauza, animacja. */
40	export class Runner {
41	  state: RunState = 'idle';
42	  machine: Machine | null = null;
43	  private gen: Generator<Step, void, void> | null = null;
44	  private anim: Anim | null = null;
45	  private shown: Pose = initialPose();
46	  private raf = 0;
47	  private last = 0;
48	  speed = 3;
49	  private stepCount = 0;
50	  private program: Program | null = null;
51	  private totalCost: number | null = null;
52	  ghost: Segment[] | null = null;
53	
54	  constructor(private sink: RunnerSink) {}
55	
56	  /** Wysyła do widoku bieżącą scenę (np. po zbudowaniu interfejsu). */
57	  refresh(): void {
58	    this.pushScene();
59	  }
60	
61	  get segments(): Segment[] {
62	    return this.machine ? this.machine.segments : [];
63	  }
64	
65	  // ----- polecenia ------------------------------------------------------
66	
67	  /** Uruchamia program od początku. `animate=false` wykonuje wszystko od razu. */
68	  run(source: string, mode: Mode, animate = true): { segments: Segment[]; error: LogoError | null } {
69	    this.stop();
70	    const m = this.begin(source, mode);
71	    if (!m) return { segments: [], error: this.parseError };
72	    const rate = animate ? SPEEDS[this.speed]!.ops : Infinity;
73	    if (rate === Infinity) {
74	      this.drain();
75	      return { segments: m.segments, error: m.error };
76	    }
77	    this.setState('running');
78	    this.sink.message('Wykonywanie programu…');
79	    this.startLoop();
80	    return { segments: m.segments, error: null };
81	  }
82	
83	  /** Jeden krok; w razie potrzeby rozpoczyna program w stanie wstrzymanym. */
84	  step(source: string, mode: Mode): void {
85	    if (this.state === 'idle' || this.state === 'finished') {
86	      this.stop();
87	      if (!this.begin(source, mode)) return;
88	      this.setState('paused');
89	    } else if (this.state === 'running') {
90	      this.setState('paused');
91	    }
92	    this.advanceOneStep();
93	  }
94	
95	  pause(): void {
96	    if (this.state === 'running') {
97	      this.setState('paused');
98	      this.sink.message('Wstrzymano — użyj „Wznów” albo „Krok”.');
99	    }
100	  }
101	
102	  resume(): void {
103	    if (this.state === 'paused') {
104	      this.setState('running');
105	      this.sink.message('Wykonywanie programu…');
106	      this.startLoop();
107	    }
108	  }
109	
110	  togglePause(): void {
111	    if (this.state === 'running') this.pause();
112	    else if (this.state === 'paused') this.resume();
113	  }
114	
115	  /** Zatrzymuje wykonanie, zostawiając rysunek (np. po edycji kodu). */
116	  halt(): void {
117	    if (this.state === 'running' || this.state === 'paused') {
118	      this.cancelLoop();
119	      this.gen = null;
120	      this.commit(); // dokończ rysowanie bieżącego kroku, żeby nie zostawić odcinka w połowie
121	      this.sink.line(null);
122	      this.setState('idle');
123	    }
124	  }
125	
126	  /** Czyści rysunek i przywraca żółwia na miejsce. */
127	  reset(): void {
128	    this.stop();
129	    this.machine = null;
