213	   * program zmieścił się w czasie przypisanym do poziomu.
214	   */
215	  private effectiveRate(): number {
216	    const lvl = SPEEDS[this.speed]!;
217	    if (lvl.ops === Infinity || !Number.isFinite(lvl.maxSeconds)) return lvl.ops;
218	    if (this.totalCost === null) {
219	      let total = 0;
220	      if (this.program) {
221	        for (const st of new Machine(this.program).steps()) total += st.cost;
222	      }
223	      this.totalCost = total;
