291	  private tick = (now: number): void => {
292	    this.raf = 0;
293	    const dt = Math.min(0.1, (now - this.last) / 1000);
294	    this.last = now;
295	    if (!this.machine || !this.gen) {
296	      if (this.state === 'running') this.setState('idle');
297	      return;
298	    }
299	    // Pauza: dokończ tylko trwającą animację kroku.
300	    const paused = this.state !== 'running';
301	    let budget = dt;
302	    const t0 = performance.now();
303	    for (;;) {
304	      if (!this.anim) {
305	        if (paused) break;
306	        if (!this.fetch()) return;
307	      }
308	      const a = this.anim!;
309	      const need = a.dur - a.elapsed;
310	      if (budget >= need) {
311	        budget -= need;
312	        this.commit();
313	        if (paused) break;
314	        if (performance.now() - t0 > 14) break; // oddaj sterowanie przeglądarce
315	      } else {
316	        a.elapsed += budget;
317	        budget = 0;
318	        if (a.dur >= TWEEN_MIN_DUR) this.pushPartial();
319	        break;
320	      }
321	    }
322	    if (this.state === 'running' || this.anim) this.raf = requestAnimationFrame(this.tick);
323	  };
324	
325	  // ----- scena ----------------------------------------------------------
326	
327	  private pushScene(): void {
328	    const m = this.machine;
329	    const segs = m ? m.segments : [];
330	    this.sink.scene({
331	      segments: segs,
332	      count: segs.length,
333	      partial: null,
334	      pose: this.shown,
335	      showTurtle: true,
336	      ghost: this.ghost,
337	    });
338	  }
339	
340	  /** Pokazuje stan pośredni trwającego kroku (żółw w ruchu, odcinek rośnie). */
341	  private pushPartial(): void {
342	    const a = this.anim;
343	    const m = this.machine;
344	    if (!a || !m) return;
345	    const t = a.dur > 0 ? Math.min(1, a.elapsed / a.dur) : 1;
346	    const st = a.step;
347	    let pose = a.after;
348	    let partial: Segment | null = null;
349	    let count = m.segments.length;
350	    if (st.move) {
351	      const [fx, fy, fz] = st.move.from;
352	      const [tx, ty, tz] = st.move.to;
353	      const pos: [number, number, number] = [fx + (tx - fx) * t, fy + (ty - fy) * t, fz + (tz - fz) * t];
354	      pose = { ...(st.resetOrientation ? (t < 1 ? a.before : a.after) : a.after), pos };
355	      if (st.seg) {
356	        count -= 1;
357	        partial = { from: st.seg.from, to: pos, color: st.seg.color, width: st.seg.width };
358	      }
359	    } else if (st.rot) {
360	      pose = rotatePose(a.before, st.rot.axis, st.rot.deg * t);
361	    }
362	    this.sink.scene({ segments: m.segments, count, partial, pose, showTurtle: true, ghost: this.ghost });
363	  }
364	}
