366	function odcinkow(n: number): string {
367	  if (n === 1) return 'odcinek';
368	  const m10 = n % 10;
369	  const m100 = n % 100;
370	  return m10 >= 2 && m10 <= 4 && !(m100 >= 12 && m100 <= 14) ? 'odcinki' : 'odcinków';
371	}
372	
373	function operacji(n: number): string {
374	  if (n === 1) return 'operacja';
375	  const m10 = n % 10;
376	  const m100 = n % 100;
377	  return m10 >= 2 && m10 <= 4 && !(m100 >= 12 && m100 <= 14) ? 'operacje' : 'operacji';
378	}
379	
380	export { odcinkow, operacji };
