// Independent reference: orientation as 3x3 matrix R with columns = local axes expressed in world coords.
// local axes: x_l = right, y_l = heading, z_l = up. Start: R = I (right=X, heading=Y, up=Z) -> columns (X, Y, Z)
type M = number[][];
const I3: M = [[1,0,0],[0,1,0],[0,0,1]];
const mul = (A: M, B: M): M => A.map((_, i) => B[0]!.map((_, j) => A[i]![0]! * B[0]![j]! + A[i]![1]! * B[1]![j]! + A[i]![2]! * B[2]![j]!));
const rad = (d: number) => d * Math.PI / 180;
const Rx = (a: number): M => [[1,0,0],[0,Math.cos(a),-Math.sin(a)],[0,Math.sin(a),Math.cos(a)]];
const Ry = (a: number): M => [[Math.cos(a),0,Math.sin(a)],[0,1,0],[-Math.sin(a),0,Math.cos(a)]];
const Rz = (a: number): M => [[Math.cos(a),-Math.sin(a),0],[Math.sin(a),Math.cos(a),0],[0,0,1]];
// spec: 
// gora a: heading (local y) rotates toward up (local z) about right (local x): Rx(+a) takes y->z (positive).
// pp a: up (local z) rotates toward right (local x) about heading (local y): Ry(+a) takes z->x. 
// pw a: heading (y) toward right (x) about up: Rz(-a) takes y -> x. 
const cmds: Record<string, (a: number) => M> = {
  gora: a => Rx(rad(a)), dol: a => Rx(rad(-a)), pp: a => Ry(rad(a)), pl: a => Ry(rad(-a)), pw: a => Rz(rad(-a)), lw: a => Rz(rad(a)),
};
function ref(prog: [string, number][]) {
  let R = I3; let p = [0,0,0]; const segs: number[][] = [];
  for (const [c, v] of prog) {
    if (c === 'np' || c === 'ws') {
      const d = c === 'np' ? v : -v;
      const h = [R[0]![1]!, R[1]![1]!, R[2]![1]!];
      const q = [p[0]! + h[0]! * d, p[1]! + h[1]! * d, p[2]! + h[2]! * d];
      segs.push([...p, ...q]); p = q;
    } else R = mul(R, cmds[c]!(v));
  }
  return segs;
}
function rnd(seed: number) { let s = seed; return () => (s = (s * 1664525 + 1013904223) % 4294967296) / 4294967296; }
const names = ['gora','dol','pp','pl','pw','lw','np','np','ws'];
let bad = 0;
for (let k = 0; k < 400; k++) {
  const r = rnd(k + 1);
  const n = 1 + Math.floor(r() * 25);
