import { run } from './h.ts';
import { EXAMPLES } from '/work/src/data/examples.ts';
let s = 12345; const rnd = () => (s = (s * 1664525 + 1013904223) % 4294967296) / 4294967296;
const pick = <T,>(a: T[]) => a[Math.floor(rnd() * a.length)]!;
const vocab = ['np','ws','pw','lw','pod','opu','kolor','grubosc','powtorz','niech','jeśli','jeżeli','stop','dom','czyść','gora','dol','pp','pl','oto','już','ma:','x','y','kwadrat','f',':x',':f','nrpowt','repcount','5','0','12.5','.5','90','-','+','*','/','(',')','[',']',',','<','>','=','<=','>=','<>','"#16866a"','"#zzz"','"','\n','\n','\n',';','1e3','5.',':','end','to','NaN','é','😀','\t','\r','\r\n','x1','_a','100000','10000','10001','0.1','3'];
const bad: string[] = [];
let slow = 0, thrown = 0, N = 30000;
const t0 = performance.now();
function check(src: string, mode: '2d'|'3d') {
  const r = run(src, mode);
  if ((r as any).threw) { thrown++; if (bad.length < 10) bad.push('THREW ' + JSON.stringify(src) + '\n' + (r as any).threw.split('\n').slice(0,3).join('\n')); return; }
  if (r.ms > 500) { slow++; if (bad.length < 10) bad.push('SLOW ' + r.ms + ' ' + JSON.stringify(src)); }
  if (r.error) {
    if (!r.error.message || typeof r.error.line !== 'number' || typeof r.error.column !== 'number' || r.error.line < 1 || r.error.column < 1 || !Number.isInteger(r.error.line) || !Number.isInteger(r.error.column)) { if (bad.length < 10) bad.push('BADERR ' + JSON.stringify(src) + JSON.stringify(r.error)); }
    // parse error -> no segments
  }
  for (const sg of r.segments) {
    for (const v of [...sg.from, ...sg.to]) if (!Number.isFinite(v) || Math.abs(v) > 100000) { if (bad.length < 10) bad.push('BADSEG ' + JSON.stringify(src)); return; }
    if (!/^#[0-9a-f]{6}$/.test(sg.color) || !Number.isInteger(sg.width) || sg.width < 1 || sg.width > 12) { if (bad.length < 10) bad.push('BADSTYLE ' + JSON.stringify(src)); return; }
  }
}
for (let i = 0; i < N; i++) {
  const mode = rnd() < 0.5 ? '2d' : '3d';
  let src: string;
  if (i % 3 === 0) { const n = 1 + Math.floor(rnd() * 30); src = Array.from({length: n}, () => pick(vocab)).join(rnd() < 0.8 ? ' ' : ''); }
  else {
    // mutate example
    const ex = pick(EXAMPLES).source; const arr = ex.split('');
    const m = 1 + Math.floor(rnd() * 4);
    for (let k = 0; k < m; k++) {
      const p = Math.floor(rnd() * arr.length); const op = rnd();
      if (op < 0.4) arr.splice(p, 1); else if (op < 0.8) arr.splice(p, 0, pick(vocab) + (rnd() < 0.5 ? ' ' : '')); else arr[p] = pick(vocab);
    }
    src = arr.join('');
  }
  check(src, mode as any);
}
console.log('done', N, 'in', (performance.now() - t0).toFixed(0) + 'ms', 'thrown', thrown, 'slow', slow);
for (const b of bad) console.log(b);
