import { run } from './h.ts';
let s = 777; const rnd = () => (s = (s * 1664525 + 1013904223) % 4294967296) / 4294967296;
const pick = <T,>(a: T[]) => a[Math.floor(rnd() * a.length)]!;
const lines = ['oto f ma: a, b','oto g','oto g ma: x','oto f :a :b','oto h :a','już','end','  już','f 1 2','g','g 3','h 4','np a','np b','np x','np :a','powtorz 2 [','powtorz a [','jeśli a > 1 [','jeżeli a < b [',']','] [','[',']]','stop','niech x a + 1','niech a 5','niech g 2','np x + 1','dom','czyść','kolor "#112233"','grubosc a','grubosc 2','pp 10','gora 10','np nrpowt','f g 2','g f 1 2','pw 90 np 10','oto f','; comment','', 'niech f 3', 'oto stop', 'f f f f f', 'g g g', 'np 10 -5', 'np a /0', 'ws 1', 'to g', 'oto g ma:', 'oto ma ma: ma'];
let thrown = 0, bad: string[] = [];
const t0 = performance.now();
for (let i = 0; i < 60000; i++) {
  const n = 1 + Math.floor(rnd() * 14);
  const src = Array.from({length: n}, () => pick(lines)).join(rnd() < 0.9 ? '\n' : ' ');
  const r = run(src, rnd() < 0.5 ? '2d' : '3d');
  if ((r as any).threw) { thrown++; if (bad.length < 5) bad.push(JSON.stringify(src) + '\n' + (r as any).threw.split('\n').slice(0, 4).join('\n')); }
  else if (r.ms > 300 && bad.length < 5) bad.push('SLOW ' + r.ms + JSON.stringify(src));
  else if (r.error && (r.error.line < 1 || r.error.column < 1 || !r.error.message)) bad.push('BADERR ' + JSON.stringify(src));
}
console.log('done', (performance.now() - t0).toFixed(0) + 'ms thrown', thrown); for (const b of bad) console.log(b);
// weird inputs to runSource
import { runSource } from '/work/src/lang/index.ts';
for (const [a, b] of [[undefined, '2d'], [null, '3d'], [123, '2d'], ['np 5', undefined], ['np 5', '3D'], ['np 5', ' 3d'], ['gora 5', 'x']] as any[]) {
  try { const r = runSource(a, b); console.log(JSON.stringify(a), JSON.stringify(b), r.segments.length, r.error && r.error.message.slice(0, 40)); } catch (e) { console.log('THREW for', a, b, String(e)); }
}
EOF
