setDescription(text: string): void {
  this.canvas.setAttribute('aria-label', text);
}

// ----- rozmiar i rysowanie --------------------------------------------

protected resize(): void {
  const r = this.el.getBoundingClientRect();
  const w = Math.max(40, Math.round(r.width));
  const hgt = Math.max(40, Math.round(r.height));
  const dpr = Math.min(3, window.devicePixelRatio || 1);
  if (w === this.width && hgt === this.height && dpr === this.dpr && this.canvas.width) return;
  const first = !this.canvas.width;
  this.width = w;
  this.height = hgt;
  this.dpr = dpr;
  this.canvas.width = Math.round(w * dpr);
  this.canvas.height = Math.round(hgt * dpr);
  this.canvas.style.width = `${w}px`;
  this.canvas.style.height = `${hgt}px`;
  this.onResized(first);
  this.invalidate();
}

protected onResized(_first: boolean): void {}

invalidate(): void {
  if (this.raf) return;
  this.raf = requestAnimationFrame((t) => {
    this.raf = 0;
    this.frame(t);
  });
}

private frame(now: number): void {
  if (this.anim) {
    const a = this.anim;
    const k = clamp((now - a.t0) / a.dur, 0, 1);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    a.step(e);
    if (k >= 1) {
      this.anim = null;
      a.done?.();
    } else this.invalidate();
  }
  this.paintNow();
}

paintNow(): void {
  if (!this.canvas.width) this.resize();
  const ctx = this.ctx;
  ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
  this.draw(ctx, this.width, this.height, { palette: this.palette, exporting: false });
}

protected abstract draw(ctx: CanvasRenderingContext2D, w: number, h: number, opts: DrawOpts): void;

