import type { Mode } from '../lang/ast';
import type { Route } from './router';

/** Kodowanie programu w adresie URL: base64url, opcjonalnie po kompresji deflate. */

function toBase64Url(bytes: Uint8Array): string {
  let bin = '';
  const CH = 0x8000;
  for (let i = 0; i < bytes.length; i += CH) bin += String.fromCharCode(...bytes.subarray(i, i + CH));
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromBase64Url(s: string): Uint8Array {
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function pipe(bytes: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  const writer = stream.writable.getWriter();
  void writer.write(bytes as unknown as BufferSource);
  void writer.close();
  const buf = await new Response(stream.readable).arrayBuffer();
  return new Uint8Array(buf);
}

export async function encodeProgram(source: string): Promise<string> {
  const raw = new TextEncoder().encode(source);
  const plain = 'u' + toBase64Url(raw);
  if (typeof CompressionStream === 'undefined') return plain;
  try {
    const z = 'z' + toBase64Url(await pipe(raw, new CompressionStream('deflate-raw')));
    return z.length < plain.length ? z : plain;
  } catch {
    return plain;
  }
}

export async function decodeProgram(payload: string): Promise<string> {
  const kind = payload[0];
  const bytes = fromBase64Url(payload.slice(1));
  if (kind === 'u') return new TextDecoder().decode(bytes);
  if (kind === 'z') {
    if (typeof DecompressionStream === 'undefined') throw new Error('Ta przeglądarka nie potrafi odczytać skompresowanego linku.');
    return new TextDecoder().decode(await pipe(bytes, new DecompressionStream('deflate-raw')));
  }
  throw new Error('Nieznany format linku.');
}

export function baseUrl(): string {
  return location.href.split('#')[0]!;
}

export async function buildPermalink(mode: Mode, source: string, base: string = baseUrl()): Promise<string> {
  const kod = await encodeProgram(source);
  return `${base}#/?tryb=${mode}&kod=${kod}`;
}

export interface SharedProgram {
  mode: Mode;
  payload: string;
}

/** Wyciąga z adresu tryb i zakodowany program (jeśli są). */
export function readPermalink(route: Route): SharedProgram | null {
  const kod = route.query.get('kod');
  if (!kod) return null;
  const tryb = route.query.get('tryb');
  return { mode: tryb === '3d' ? '3d' : '2d', payload: kod };
}
import type { Mode } from '../lang/ast';
import { LIMITS } from '../lang';

export function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.rel = 'noopener';
  a.style.display = 'none';
  document.body.appendChild(a);
  a.click();
  setTimeout(() => {
    a.remove();
    URL.revokeObjectURL(url);
  }, 2000);
}

export function downloadProgram(source: string, name: string): void {
  downloadBlob(new Blob([source], { type: 'text/plain;charset=utf-8' }), name);
}

export function slug(s: string): string {
  return (
    s
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/ł/g, 'l')
      .replace(/Ł/g, 'L')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '') || 'program'
  );
}

export function programFileName(mode: Mode, title?: string): string {
  return `${slug(title ?? 'logomocja')}-${mode}.logo`;
}

const THREE_D_WORDS = /(^|[^\p{L}\p{N}_])(gora|góra|dol|dół|pp|pl|przechylprawo|przechyllewo|pitchup|pitchdown|rr|rl|rollright|rollleft)(?![\p{L}\p{N}_])/iu;

/** Zgaduje tryb dla wczytywanego pliku: nazwa pliku lub użycie poleceń 3D. */
export function guessMode(fileName: string, source: string, current: Mode): Mode {
  if (/(^|[^a-z0-9])3d(\.|$|[^a-z0-9])/i.test(fileName)) return '3d';
  if (/(^|[^a-z0-9])2d(\.|$|[^a-z0-9])/i.test(fileName)) return '2d';
  const noComments = source.replace(/;.*$/gm, '');
  if (THREE_D_WORDS.test(noComments)) return '3d';
  return current;
}

export const MAX_FILE_BYTES = 1_000_000;

export async function readTextFile(file: File): Promise<string> {
  if (file.size > MAX_FILE_BYTES) throw new Error(`Plik jest zbyt duży (${Math.round(file.size / 1024)} KB). Program może mieć najwyżej ${LIMITS.maxChars.toLocaleString('pl-PL')} znaków.`);
