  if (errKind !== refKind) bad = `error kind impl=${errKind} ref=${refKind}`;
  else if (gotSegs.length !== ref.segs.length || gotSegs.some((g, i) => g.some((v, j) => typeof v === 'number' ? Math.abs(v - (ref.segs[i]![j] as number)) > 1e-9 : v !== ref.segs[i]![j]))) bad = `segments differ impl=${gotSegs.length} ref=${ref.segs.length}`;
