import { runSource } from './lang.mjs';
const nestIf = (d, inner) => 'jeśli 1 < 2 ['.repeat(d) + inner + ']'.repeat(d);
function go(label, src, mode='2d') { const t0 = performance.now(); const r = runSource(src, mode); console.log(label.padEnd(44), r.error ? `${r.error.line}:${r.error.column} ${r.error.message.slice(0,70)}` : 'ok', 'segs', r.segments.length, (performance.now()-t0).toFixed(0)+'ms'); }
for (const d of [5, 15, 25, 31]) {
  go(`recursion 32 x ${d} nested ifs`, `oto r ma: n\n np 0\n ${nestIf(d, 'jeśli n > 1 [ r n - 1 ]')}\njuż\nr 32`);
}
// the maximal legal nesting: 31 ifs + 1 = 32 brackets, 32 frames
go('31 ifs + 1, 32 frames', `oto r ma: n\n ${nestIf(31, 'jeśli n > 1 [ r n - 1 ]')}\njuż\nr 32`);
// repeats as frames mixed with ifs: 16 frames each with repeat
go('call+repeat alternating', `oto r ma: n\n powtorz 1 [ ${nestIf(30, 'jeśli n > 1 [ r n - 1 ]')} ]\njuż\nr 16`);
go('call+repeat alternating, 16 deep, np inside', `oto r ma: n\n powtorz 1 [ ${nestIf(30, 'jeśli n > 1 [ r n - 1 ] np 1')} ]\njuż\nr 16`);
EOF
