import { withPage } from './lib.mjs';
await withPage(async (page) => {
  const ed = page.locator('textarea.editor-input');
  await ed.click(); await page.keyboard.press('Control+A'); await page.keyboard.type('; moj szkic\nnp 33');
  await page.waitForTimeout(400);
  const drop = async (name, text, target = '.workspace') => {
    await page.evaluate(async ([name, text, target]) => {
      const dt = new DataTransfer();
      dt.items.add(new File([text], name, { type: 'text/plain' }));
      const el = document.querySelector(target);
      for (const t of ['dragenter', 'dragover']) el.dispatchEvent(new DragEvent(t, { dataTransfer: dt, bubbles: true, cancelable: true }));
      window.__dropClass = el.className;
      el.dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
    }, [name, text, target]);
  };
  await page.evaluate(() => {});
  // show drop-target highlight
  await page.evaluate(() => { const dt = new DataTransfer(); dt.items.add(new File(['x'], 'a.logo')); document.querySelector('.workspace').dispatchEvent(new DragEvent('dragenter', { dataTransfer: dt, bubbles: true, cancelable: true })); });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/review/ui/31-a-drop-hint.png' });
  await drop('zrzut.logo', 'powtorz 8 [np 70 pw 45]');
  await page.waitForTimeout(800);
  console.log('after drop value:', JSON.stringify(await ed.inputValue()), '| status:', await page.locator('.status-text').innerText(), '| stash', await page.locator('.filebar .count').innerText(), '| class', await page.evaluate(() => document.querySelector('.workspace').className));
  // dropping on page outside workspace (header) -> browser would navigate to file!
  const nav = await page.evaluate(() => { const dt = new DataTransfer(); dt.items.add(new File(['x'], 'a.logo')); const ev = new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }); document.querySelector('header').dispatchEvent(ev); return ev.defaultPrevented; });
  console.log('drop outside workspace defaultPrevented (false => browser would navigate away):', nav);
  const nav2 = await page.evaluate(() => { const dt = new DataTransfer(); dt.items.add(new File(['x'], 'a.logo')); const ev = new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }); document.querySelector('.view-host').dispatchEvent(ev); return ev.defaultPrevented; });
  console.log('drop on view defaultPrevented:', nav2);
}, {});
EOF
