import { withPage } from './lib.mjs';
await withPage(async (page) => {
  const ed = page.locator('textarea.editor-input');
  const type = async (t) => { await ed.click(); await page.keyboard.press('Control+A'); await page.keyboard.type(t); await page.waitForTimeout(200); };
  await type('; draft 2d\nnp 11');
  await page.getByText('3D', { exact: true }).click(); await page.waitForTimeout(400);
  console.log('3d default shown:', JSON.stringify((await ed.inputValue()).slice(0, 30)));
  await type('; draft 3d\ngora 20 np 22');
  await page.getByText('2D', { exact: true }).click(); await page.waitForTimeout(400);
  console.log('back to 2d:', JSON.stringify(await ed.inputValue()));
  await page.reload(); await page.waitForFunction(() => window.logomocja); await page.waitForTimeout(700);
  console.log('after reload mode', await page.evaluate(() => document.querySelector('.seg-input:checked').value), JSON.stringify(await ed.inputValue()));
  await page.getByText('3D', { exact: true }).click(); await page.waitForTimeout(400);
  console.log('3d after reload:', JSON.stringify(await ed.inputValue()));
  await page.reload(); await page.waitForFunction(() => window.logomocja); await page.waitForTimeout(700);
  console.log('reload in 3d mode:', await page.evaluate(() => document.querySelector('.seg-input:checked').value));
  // clear storage keys sanity
  console.log(await page.evaluate(() => Object.keys(localStorage).join(',')));
  // empty editor persists as empty after reload?
  await type('x'); await ed.click(); await page.keyboard.press('Control+A'); await page.keyboard.press('Delete'); await page.waitForTimeout(300);
  await page.reload(); await page.waitForFunction(() => window.logomocja); await page.waitForTimeout(700);
  console.log('emptied draft after reload:', JSON.stringify((await ed.inputValue()).slice(0, 40)), '| placeholder visible?', await ed.getAttribute('placeholder'));
  await page.screenshot({ path: '/tmp/review/ui/35-empty-editor.png' });
}, {});
EOF
