import { chromium } from 'playwright';
const browser = await chromium.launch();
for (const base of ['http://localhost:4174/Logomocja/builds/x/', 'http://localhost:4173/']) {
  const ctx = await browser.newContext({ viewport: { width: 1360, height: 800 } });
  const page = await ctx.newPage();
  const fails = [], external = [], logs = [];
  page.on('requestfailed', (r) => fails.push(r.url() + ' ' + r.failure()?.errorText));
  page.on('response', (r) => { if (r.status() >= 400) fails.push(r.status() + ' ' + r.url()); });
  page.on('request', (r) => { if (!r.url().startsWith(new URL(base).origin) && !r.url().startsWith('data:') && !r.url().startsWith('blob:')) external.push(r.url()); });
  page.on('console', (m) => { if (m.type() !== 'log') logs.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', (e) => logs.push('[pageerror] ' + e.message));
  await page.goto(base); await page.waitForFunction(() => window.logomocja); await page.waitForTimeout(800);
  console.log('==', base, 'version', await page.evaluate(() => window.logomocja.version));
  await page.getByRole('link', { name: /Wyzwania/ }).click(); await page.waitForTimeout(400);
  console.log('nav url:', page.url());
  await page.locator('.challenge-card a').nth(1).click(); await page.waitForTimeout(500);
  console.log('challenge url:', page.url(), '|', await page.title());
  await page.reload(); await page.waitForFunction(() => window.logomocja); await page.waitForTimeout(800);
  console.log('after reload title:', await page.title(), '| task visible:', await page.locator('.task-title').innerText());
  await page.goto(base + '#/polecenia/procedury'); await page.reload(); await page.waitForFunction(() => window.logomocja); await page.waitForTimeout(800);
  console.log('deeplink top:', await page.evaluate(() => Math.round(document.getElementById('ref-procedury').getBoundingClientRect().top)));
  // run via test hook
  const r = await page.evaluate(async () => { const a = window.logomocja.run('powtorz 4 [np 10 pw 90]', '2d'); const b = await window.logomocja.open('powtorz 3 [np 10 pw 120]', '2d'); return [a.segments?.length ?? (await a).segments.length, b.segments.length, b.error]; });
  console.log('hook', JSON.stringify(r));
  // manifest/favicon
  const links = await page.evaluate(() => [...document.querySelectorAll('link[href]')].map((l) => l.getAttribute('href') + ' -> ' + l.href));
  console.log(links.join(' | '));
  console.log('fails:', fails.join(' ; ') || 'none', '| external:', external.join(' ; ') || 'none', '| logs:', logs.join(' ; ') || 'none');
  await ctx.close();
}
await browser.close();
EOF
