    await page.evaluate(() => { window.__ft = []; let last = performance.now(); const f = (t) => { window.__ft.push(t - last); last = t; if (window.__run) requestAnimationFrame(f); }; window.__run = true; requestAnimationFrame(f); });
    await page.getByRole('button', { name: 'Uruchom' }).click();
    const t0 = Date.now();
    await page.waitForFunction(() => document.querySelector('.workspace').dataset.run === 'finished', null, { timeout: 60000 });
    const dur = Date.now() - t0;
    const ft = await page.evaluate(() => { window.__run = false; return window.__ft; });
    ft.sort((a, b) => a - b);
    console.log(ex, 'anim duration ms', dur, 'frames', ft.length, 'median', ft[Math.floor(ft.length / 2)]?.toFixed(1), 'p95', ft[Math.floor(ft.length * 0.95)]?.toFixed(1), 'max', ft[ft.length - 1]?.toFixed(1));
  }
}, {});
EOF
