import { withPage } from './lib.mjs';
import { chromium } from 'playwright';
const ok = (c, m) => console.log((c ? 'PASS' : 'FAIL') + ' ' + m);
const bboxOfDrawing = (page) => page.evaluate(() => {
  const c = [...document.querySelectorAll('.view-canvas')].find((x) => x.offsetParent);
  const ctx = c.getContext('2d'); const w = c.width, h = c.height;
  const d = ctx.getImageData(0, 0, w, h).data; let minx = w, maxx = 0, miny = h, maxy = 0;
  for (let y = 0; y < h; y += 2) for (let x = 0; x < w; x += 2) { const i = (y * w + x) * 4; if (d[i + 1] > 100 && d[i] < 80 && d[i + 2] < 140 && d[i + 1] - d[i] > 40) { if (x < minx) minx = x; if (x > maxx) maxx = x; if (y < miny) miny = y; if (y > maxy) maxy = y; } }
  return { w: maxx - minx, h: maxy - miny, cw: w, ch: h };
});
// A1: fresh permalink
await withPage(async (page, ctx) => {
  await page.evaluate(() => window.logomocja.open('powtorz 4 [np 120 pw 90]', '2d'));
  await page.click('.transport button[aria-label="Link"]');
  const url = await page.inputValue('#permalink-input');
  const p2 = await ctx.newPage();
  await p2.setViewportSize({ width: 1360, height: 800 });
  await p2.goto(url); await p2.waitForTimeout(1000);
  const b = await bboxOfDrawing(p2);
  ok(b.w > 250 && b.h > 250, 'A1 fresh permalink fits drawing: ' + JSON.stringify(b));
  // A2: from gallery
  await p2.goto('http://localhost:4173/#/przyklady'); await p2.waitForTimeout(600);
  await p2.click('article[data-example="kwadrat"] button:has-text("Wczytaj")'); await p2.waitForTimeout(800);
  const b2 = await bboxOfDrawing(p2);
  ok(b2.w > 250 && b2.h > 250, 'A2 gallery load fits drawing: ' + JSON.stringify(b2));
  await p2.goto('http://localhost:4173/#/polecenia'); await p2.waitForTimeout(600);
  await p2.click('#ref-start button:has-text("Wypróbuj")'); await p2.waitForTimeout(800);
  const b3 = await bboxOfDrawing(p2);
  ok(b3.w > 200 && b3.h > 200, 'A2 reference try fits drawing: ' + JSON.stringify(b3));
  ok((await p2.textContent('.toasts')).indexOf('zachowany') < 0, 'reference snippet does not clutter stash');
});
// A2 hook when loaded at another route
const browser = await chromium.launch();
const pg = await browser.newPage({ viewport: { width: 1360, height: 800 } });
await pg.goto('http://localhost:4173/#/wyzwania'); await pg.waitForFunction(() => window.logomocja);
await pg.evaluate(() => window.logomocja.open('powtorz 4 [np 100 pw 90]', '2d'));
const b4 = await bboxOfDrawing(pg);
ok(b4.w > 250 && b4.h > 250, 'hook after loading at #/wyzwania fits: ' + JSON.stringify(b4));
await browser.close();
EOF
