input.command:
BASE_PATH=/Logomocja/builds/x/ bun run build | tail -1 && cat > /tmp/tools/f10.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const bad = [];
page.on('response', (r) => { if (r.status() >= 400) bad.push(r.status() + ' ' + r.url()); });
page.on('console', (m) => { if (m.type() === 'error') bad.push('console: ' + m.text()); });
page.on('request', (r) => { if (!r.url().startsWith('http://localhost:4174/')) bad.push('external: ' + r.url()); });
await page.goto('http://localhost:4174/Logomocja/builds/x/');
await page.waitForFunction(() => window.logomocja);
const r = await page.evaluate(() => window.logomocja.open('powtorz 4 [np 100 pw 90]', '2d'));
for (const route of ['#/przyklady', '#/wyzwania/trojkat', '#/polecenia/limity', '#/']) {
  await page.goto('http://localhost:4174/Logomocja/builds/x/' + route); await page.reload(); await page.waitForTimeout(500);
}
console.log('segments', r.segments.length, 'problems:', JSON.stringify(bad));
await browser.close();
EOF
cd /tmp/tools && . ./env.sh && node f10.mjs; cd /work && bun run build | tail -1

